window.SAT_VOCABULARY = [{"number":1,"word":"Abate","partOfSpeech":"","meaning":"To become less intense or widespread; to decrease.","synonyms":["lessen","diminish","subside"],"antonyms":[],"example":"The storm began to abate after several hours of heavy rain.","href":"SAT_Words_1_25.html"},{"number":2,"word":"Aberration","partOfSpeech":"","meaning":"A departure from what is normal, expected, or usual.","synonyms":["anomaly","deviation","exception"],"antonyms":[],"example":"The student's low quiz score was an aberration because she usually earned A's.","href":"SAT_Words_1_25.html"},{"number":3,"word":"Abhor","partOfSpeech":"","meaning":"To hate deeply or regard with intense dislike.","synonyms":["detest","loathe","despise"],"antonyms":[],"example":"Many people abhor dishonesty in public officials.","href":"SAT_Words_1_25.html"},{"number":4,"word":"Acclaim","partOfSpeech":"","meaning":"Enthusiastic praise or approval; to praise enthusiastically.","synonyms":["praise","applause","commendation"],"antonyms":[],"example":"The novel received widespread acclaim from critics.","href":"SAT_Words_1_25.html"},{"number":5,"word":"Acquiesce","partOfSpeech":"","meaning":"To accept or comply reluctantly without arguing further.","synonyms":["yield","comply","consent"],"antonyms":[],"example":"After hours of discussion, she acquiesced to the committee's decision.","href":"SAT_Words_1_25.html"},{"number":6,"word":"Acrimony","partOfSpeech":"","meaning":"Bitterness or hostility in speech, behavior, or feeling.","synonyms":["bitterness","resentment","hostility"],"antonyms":[],"example":"The discussion ended with unexpected acrimony.","href":"SAT_Words_1_25.html"},{"number":7,"word":"Adept","partOfSpeech":"","meaning":"Highly skilled or proficient at doing something.","synonyms":["skilled","proficient","capable"],"antonyms":[],"example":"She is adept at solving complex equations.","href":"SAT_Words_1_25.html"},{"number":8,"word":"Adversity","partOfSpeech":"","meaning":"A difficult or unfavorable situation; hardship.","synonyms":["hardship","difficulty","struggle"],"antonyms":[],"example":"Despite adversity, she graduated with honors.","href":"SAT_Words_1_25.html"},{"number":9,"word":"Aesthetic","partOfSpeech":"","meaning":"Concerned with beauty, art, or visual appearance.","synonyms":["artistic","visual","beautiful"],"antonyms":[],"example":"The architect designed the library to improve its aesthetic appeal.","href":"SAT_Words_1_25.html"},{"number":10,"word":"Agile","partOfSpeech":"","meaning":"Able to move quickly and easily; mentally quick and flexible.","synonyms":["nimble","swift","flexible"],"antonyms":[],"example":"The agile athlete changed direction before the defender could react.","href":"SAT_Words_1_25.html"},{"number":11,"word":"Alienate","partOfSpeech":"","meaning":"To cause someone to feel isolated, estranged, or no longer supportive.","synonyms":["isolate","estrange","drive away"],"antonyms":[],"example":"His rude comments alienated several of his friends.","href":"SAT_Words_1_25.html"},{"number":12,"word":"Ambiguous","partOfSpeech":"","meaning":"Unclear or open to more than one interpretation.","synonyms":["vague","unclear","uncertain"],"antonyms":[],"example":"The instructions were ambiguous, so students asked for clarification.","href":"SAT_Words_1_25.html"},{"number":13,"word":"Ambivalent","partOfSpeech":"","meaning":"Having mixed or conflicting feelings about something.","synonyms":["conflicted","uncertain","torn"],"antonyms":[],"example":"She felt ambivalent about moving away from her friends.","href":"SAT_Words_1_25.html"},{"number":14,"word":"Ameliorate","partOfSpeech":"","meaning":"To make a difficult situation better; to improve.","synonyms":["improve","enhance","relieve"],"antonyms":[],"example":"The reforms helped ameliorate working conditions.","href":"SAT_Words_1_25.html"},{"number":15,"word":"Amiable","partOfSpeech":"","meaning":"Friendly, pleasant, and easy to get along with.","synonyms":["friendly","agreeable","pleasant"],"antonyms":[],"example":"The amiable host greeted every guest warmly.","href":"SAT_Words_1_25.html"},{"number":16,"word":"Anomaly","partOfSpeech":"","meaning":"Something unusual that does not fit the expected pattern.","synonyms":["irregularity","deviation","oddity"],"antonyms":[],"example":"Scientists noticed an anomaly in the temperature data.","href":"SAT_Words_1_25.html"},{"number":17,"word":"Antagonize","partOfSpeech":"","meaning":"To provoke, irritate, or cause hostility in someone.","synonyms":["provoke","irritate","anger"],"antonyms":[],"example":"His comments antagonized the audience.","href":"SAT_Words_1_25.html"},{"number":18,"word":"Apathy","partOfSpeech":"","meaning":"A lack of interest, enthusiasm, or concern.","synonyms":["indifference","disinterest","unconcern"],"antonyms":[],"example":"Student apathy concerned the teachers because few students joined clubs.","href":"SAT_Words_1_25.html"},{"number":19,"word":"Appease","partOfSpeech":"","meaning":"To calm, satisfy, or reduce the anger of someone.","synonyms":["pacify","soothe","satisfy"],"antonyms":[],"example":"The company lowered prices to appease frustrated customers.","href":"SAT_Words_1_25.html"},{"number":20,"word":"Apprehensive","partOfSpeech":"","meaning":"Anxious or worried about what may happen.","synonyms":["nervous","uneasy","anxious"],"antonyms":[],"example":"She felt apprehensive before the interview.","href":"SAT_Words_1_25.html"},{"number":21,"word":"Arbitrary","partOfSpeech":"","meaning":"Based on random choice, personal whim, or no clear reason.","synonyms":["random","capricious","unreasonable"],"antonyms":[],"example":"The rule seemed arbitrary and unfair because no reason was given for it.","href":"SAT_Words_1_25.html"},{"number":22,"word":"Arduous","partOfSpeech":"","meaning":"Very difficult and requiring substantial effort.","synonyms":["difficult","strenuous","demanding"],"antonyms":[],"example":"Training for the marathon was an arduous process.","href":"SAT_Words_1_25.html"},{"number":23,"word":"Articulate","partOfSpeech":"","meaning":"Able to express ideas clearly and effectively; to express clearly.","synonyms":["eloquent","expressive","clear"],"antonyms":[],"example":"She gave an articulate explanation of her research.","href":"SAT_Words_1_25.html"},{"number":24,"word":"Aspire","partOfSpeech":"","meaning":"To aim for or seek a high goal.","synonyms":["seek","strive","aim"],"antonyms":[],"example":"Joshua aspires to earn a high SAT score.","href":"SAT_Words_1_25.html"},{"number":25,"word":"Capricious","partOfSpeech":"","meaning":"Given to sudden, unpredictable changes in mood or behavior.","synonyms":["unpredictable","erratic","impulsive"],"antonyms":[],"example":"The weather was capricious all week, changing from sun to rain without warning.","href":"SAT_Words_1_25.html"},{"number":26,"word":"Candid","partOfSpeech":"","meaning":"Honest, direct, and straightforward.","synonyms":["frank","open","truthful"],"antonyms":[],"example":"The coach gave the team a candid assessment of its performance.","href":"SAT_Words_26_50.html"},{"number":27,"word":"Catalyst","partOfSpeech":"","meaning":"A person, event, or thing that causes or speeds up change.","synonyms":["stimulus","trigger","impetus"],"antonyms":[],"example":"The invention of the smartphone was a catalyst for changes in communication.","href":"SAT_Words_26_50.html"},{"number":28,"word":"Censure","partOfSpeech":"","meaning":"Strong criticism or official disapproval; to criticize severely.","synonyms":["condemnation","rebuke","criticism"],"antonyms":[],"example":"The committee issued a censure after the official violated its rules.","href":"SAT_Words_26_50.html"},{"number":29,"word":"Clandestine","partOfSpeech":"","meaning":"Kept secret, especially because it is meant to be hidden.","synonyms":["secret","covert","concealed"],"antonyms":[],"example":"The reporters uncovered a clandestine meeting between the two groups.","href":"SAT_Words_26_50.html"},{"number":30,"word":"Cogent","partOfSpeech":"","meaning":"Clear, logical, and convincing.","synonyms":["convincing","logical","persuasive"],"antonyms":[],"example":"The student gave a cogent explanation for her conclusion.","href":"SAT_Words_26_50.html"},{"number":31,"word":"Coherent","partOfSpeech":"","meaning":"Logical, organized, and easy to understand.","synonyms":["logical","clear","orderly"],"antonyms":[],"example":"Her essay was coherent because every paragraph supported the main idea.","href":"SAT_Words_26_50.html"},{"number":32,"word":"Complacent","partOfSpeech":"","meaning":"Too satisfied with oneself or a situation, often without noticing possible problems.","synonyms":["self-satisfied","smug","unconcerned"],"antonyms":[],"example":"After winning several games, the team became complacent and stopped practicing carefully.","href":"SAT_Words_26_50.html"},{"number":33,"word":"Compelling","partOfSpeech":"","meaning":"Very convincing, persuasive, or interesting.","synonyms":["persuasive","convincing","gripping"],"antonyms":[],"example":"The documentary made a compelling case for protecting the wetlands.","href":"SAT_Words_26_50.html"},{"number":34,"word":"Concise","partOfSpeech":"","meaning":"Brief but complete; using few words without losing important meaning.","synonyms":["brief","succinct","compact"],"antonyms":[],"example":"The editor asked the writer to make the introduction more concise.","href":"SAT_Words_26_50.html"},{"number":35,"word":"Concur","partOfSpeech":"","meaning":"To agree or have the same opinion.","synonyms":["agree","consent","coincide"],"antonyms":[],"example":"Most researchers concur that the evidence needs further study.","href":"SAT_Words_26_50.html"},{"number":36,"word":"Condescending","partOfSpeech":"","meaning":"Showing that one believes one is better, smarter, or more important than others.","synonyms":["patronizing","superior","snobbish"],"antonyms":[],"example":"The professor's condescending tone made students reluctant to ask questions.","href":"SAT_Words_26_50.html"},{"number":37,"word":"Conspicuous","partOfSpeech":"","meaning":"Very noticeable; easy to see or recognize.","synonyms":["noticeable","prominent","obvious"],"antonyms":[],"example":"The bright red umbrella was conspicuous in the crowded station.","href":"SAT_Words_26_50.html"},{"number":38,"word":"Contend","partOfSpeech":"","meaning":"To argue or assert; also, to struggle or compete.","synonyms":["argue","assert","maintain"],"antonyms":[],"example":"The author contends that cities need more public green space.","href":"SAT_Words_26_50.html"},{"number":39,"word":"Contrive","partOfSpeech":"","meaning":"To devise, invent, or bring about through careful planning.","synonyms":["devise","invent","engineer"],"antonyms":[],"example":"The engineers contrived a simple device to collect rainwater.","href":"SAT_Words_26_50.html"},{"number":40,"word":"Conventional","partOfSpeech":"","meaning":"Following usual or traditional methods, ideas, or styles.","synonyms":["traditional","customary","standard"],"antonyms":[],"example":"Rather than use a conventional lecture, the teacher led a discussion.","href":"SAT_Words_26_50.html"},{"number":41,"word":"Convey","partOfSpeech":"","meaning":"To communicate, express, or make known.","synonyms":["communicate","express","transmit"],"antonyms":[],"example":"The graph conveys how the population changed over time.","href":"SAT_Words_26_50.html"},{"number":42,"word":"Corroborate","partOfSpeech":"","meaning":"To confirm or support a statement, theory, or finding with evidence.","synonyms":["confirm","support","verify"],"antonyms":[],"example":"The second witness's account corroborated the first witness's story.","href":"SAT_Words_26_50.html"},{"number":43,"word":"Credible","partOfSpeech":"","meaning":"Believable and worthy of trust.","synonyms":["believable","trustworthy","reliable"],"antonyms":[],"example":"The article cited credible sources from well-known research institutions.","href":"SAT_Words_26_50.html"},{"number":44,"word":"Cursory","partOfSpeech":"","meaning":"Quick and not thorough; giving only superficial attention.","synonyms":["hasty","superficial","brief"],"antonyms":[],"example":"He gave the report a cursory review before the meeting.","href":"SAT_Words_26_50.html"},{"number":45,"word":"Daunting","partOfSpeech":"","meaning":"Seeming difficult enough to discourage or intimidate someone.","synonyms":["intimidating","overwhelming","formidable"],"antonyms":[],"example":"Writing a 20-page research paper seemed daunting at first.","href":"SAT_Words_26_50.html"},{"number":46,"word":"Debilitate","partOfSpeech":"","meaning":"To weaken severely or reduce strength and effectiveness.","synonyms":["weaken","impair","exhaust"],"antonyms":[],"example":"The illness debilitated him for several weeks.","href":"SAT_Words_26_50.html"},{"number":47,"word":"Decorum","partOfSpeech":"","meaning":"Appropriate and polite behavior, especially in formal situations.","synonyms":["propriety","manners","etiquette"],"antonyms":[],"example":"The judge reminded everyone in the courtroom to maintain decorum.","href":"SAT_Words_26_50.html"},{"number":48,"word":"Defiant","partOfSpeech":"","meaning":"Openly resisting authority, rules, or expectations.","synonyms":["rebellious","resistant","disobedient"],"antonyms":[],"example":"The defiant student refused to follow the principal's instructions.","href":"SAT_Words_26_50.html"},{"number":49,"word":"Deliberate","partOfSpeech":"","meaning":"Careful and intentional; to consider something carefully.","synonyms":["intentional","careful","considered"],"antonyms":[],"example":"The committee took a deliberate approach to reviewing the proposal.","href":"SAT_Words_26_50.html"},{"number":50,"word":"Denounce","partOfSpeech":"","meaning":"To publicly condemn or strongly criticize.","synonyms":["condemn","criticize","rebuke"],"antonyms":[],"example":"The organization denounced the use of misleading advertisements.","href":"SAT_Words_26_50.html"},{"number":51,"word":"Deplete","partOfSpeech":"","meaning":"To use up a supply or greatly reduce the amount of something.","synonyms":["exhaust","drain","consume"],"antonyms":[],"example":"Years of overfishing can deplete the number of fish in a lake.","href":"SAT_Words_51_75.html"},{"number":52,"word":"Derive","partOfSpeech":"","meaning":"To obtain, receive, or develop something from a source.","synonyms":["obtain","gain","originate"],"antonyms":[],"example":"Many English words derive from Latin and Greek roots.","href":"SAT_Words_51_75.html"},{"number":53,"word":"Deter","partOfSpeech":"","meaning":"To discourage someone from doing something by making it seem difficult, risky, or undesirable.","synonyms":["discourage","prevent","dissuade"],"antonyms":[],"example":"High parking fees may deter visitors from driving downtown.","href":"SAT_Words_51_75.html"},{"number":54,"word":"Deviate","partOfSpeech":"","meaning":"To move away from a usual, expected, or planned path, rule, or pattern.","synonyms":["diverge","depart","stray"],"antonyms":[],"example":"The speaker deviated from her notes to answer the audience's question.","href":"SAT_Words_51_75.html"},{"number":55,"word":"Diligent","partOfSpeech":"","meaning":"Consistently hardworking, careful, and thorough.","synonyms":["industrious","hardworking","conscientious"],"antonyms":[],"example":"Because she was diligent, Maya reviewed her notes every evening before the exam.","href":"SAT_Words_51_75.html"},{"number":56,"word":"Diminish","partOfSpeech":"","meaning":"To make or become smaller, weaker, or less important.","synonyms":["lessen","decrease","reduce"],"antonyms":[],"example":"The noise from the crowd began to diminish as the show ended.","href":"SAT_Words_51_75.html"},{"number":57,"word":"Disparity","partOfSpeech":"","meaning":"A noticeable difference or inequality between two or more things.","synonyms":["difference","inequality","imbalance"],"antonyms":[],"example":"The report examined the disparity between rural and urban internet access.","href":"SAT_Words_51_75.html"},{"number":58,"word":"Divergent","partOfSpeech":"","meaning":"Moving in different directions or differing greatly in viewpoint, method, or character.","synonyms":["different","conflicting","separate"],"antonyms":[],"example":"The two scientists proposed divergent explanations for the same result.","href":"SAT_Words_51_75.html"},{"number":59,"word":"Dogmatic","partOfSpeech":"","meaning":"Expressing opinions as unquestionably true and refusing to consider other views.","synonyms":["rigid","opinionated","authoritarian"],"antonyms":[],"example":"His dogmatic response ended the discussion before anyone could offer another idea.","href":"SAT_Words_51_75.html"},{"number":60,"word":"Dubious","partOfSpeech":"","meaning":"Doubtful, uncertain, or not likely to be true.","synonyms":["questionable","doubtful","uncertain"],"antonyms":[],"example":"The claim sounded dubious because it was not supported by evidence.","href":"SAT_Words_51_75.html"},{"number":61,"word":"Eccentric","partOfSpeech":"","meaning":"Unconventional or noticeably unusual in behavior, style, or ideas.","synonyms":["unconventional","peculiar","quirky"],"antonyms":[],"example":"The eccentric inventor wore mismatched shoes and worked only at night.","href":"SAT_Words_51_75.html"},{"number":62,"word":"Eclectic","partOfSpeech":"","meaning":"Drawing ideas, styles, or elements from many different sources.","synonyms":["diverse","varied","wide-ranging"],"antonyms":[],"example":"The restaurant has an eclectic menu that includes foods from several cultures.","href":"SAT_Words_51_75.html"},{"number":63,"word":"Efficacy","partOfSpeech":"","meaning":"The ability to produce the intended or desired result; effectiveness.","synonyms":["effectiveness","success","usefulness"],"antonyms":[],"example":"The study tested the efficacy of the new teaching method.","href":"SAT_Words_51_75.html"},{"number":64,"word":"Eloquent","partOfSpeech":"","meaning":"Fluent, powerful, and persuasive in speaking or writing.","synonyms":["articulate","expressive","persuasive"],"antonyms":[],"example":"The student delivered an eloquent speech about the value of public libraries.","href":"SAT_Words_51_75.html"},{"number":65,"word":"Elusive","partOfSpeech":"","meaning":"Difficult to find, catch, understand, or achieve.","synonyms":["hard to find","evasive","slippery"],"antonyms":[],"example":"A complete answer to the mystery remained elusive for years.","href":"SAT_Words_51_75.html"},{"number":66,"word":"Empirical","partOfSpeech":"","meaning":"Based on observation, measurement, or experiment rather than theory alone.","synonyms":["observed","experimental","evidence-based"],"antonyms":[],"example":"The researchers used empirical evidence collected during a five-year study.","href":"SAT_Words_51_75.html"},{"number":67,"word":"Emulate","partOfSpeech":"","meaning":"To imitate someone or something, usually because it is admired.","synonyms":["imitate","copy","model"],"antonyms":[],"example":"Young athletes often emulate the training habits of professional players.","href":"SAT_Words_51_75.html"},{"number":68,"word":"Endorse","partOfSpeech":"","meaning":"To approve of, support publicly, or recommend.","synonyms":["support","approve","recommend"],"antonyms":[],"example":"Several health organizations endorse the campaign to encourage regular exercise.","href":"SAT_Words_51_75.html"},{"number":69,"word":"Enhance","partOfSpeech":"","meaning":"To improve the quality, value, strength, or effectiveness of something.","synonyms":["improve","strengthen","enrich"],"antonyms":[],"example":"Adding captions can enhance a video for viewers who cannot hear the audio.","href":"SAT_Words_51_75.html"},{"number":70,"word":"Engender","partOfSpeech":"","meaning":"To cause a feeling, situation, or condition to develop.","synonyms":["cause","create","generate"],"antonyms":[],"example":"Clear communication can engender trust between a school and its families.","href":"SAT_Words_51_75.html"},{"number":71,"word":"Enigma","partOfSpeech":"","meaning":"A person, thing, or situation that is mysterious and difficult to understand.","synonyms":["mystery","puzzle","riddle"],"antonyms":[],"example":"How the ancient structure was built remains an enigma to historians.","href":"SAT_Words_51_75.html"},{"number":72,"word":"Ephemeral","partOfSpeech":"","meaning":"Lasting for only a short time; temporary.","synonyms":["temporary","brief","short-lived"],"antonyms":[],"example":"The artist created an ephemeral sculpture from ice that melted by afternoon.","href":"SAT_Words_51_75.html"},{"number":73,"word":"Equitable","partOfSpeech":"","meaning":"Fair and just, especially in the way people are treated.","synonyms":["fair","just","impartial"],"antonyms":[],"example":"The principal aimed to create an equitable system for distributing school resources.","href":"SAT_Words_51_75.html"},{"number":74,"word":"Erratic","partOfSpeech":"","meaning":"Unpredictable, irregular, or not following a consistent pattern.","synonyms":["unpredictable","irregular","inconsistent"],"antonyms":[],"example":"The car's erratic engine performance made the mechanic suspect a loose connection.","href":"SAT_Words_51_75.html"},{"number":75,"word":"Exacerbate","partOfSpeech":"","meaning":"To make a problem, situation, or feeling worse.","synonyms":["worsen","aggravate","intensify"],"antonyms":[],"example":"Ignoring the leak would only exacerbate the damage to the ceiling.","href":"SAT_Words_51_75.html"},{"number":76,"word":"Exemplary","partOfSpeech":"","meaning":"Serving as an excellent example; outstanding and worthy of imitation.","synonyms":["excellent","outstanding","model"],"antonyms":[],"example":"The student's exemplary research paper became a model for next year's class.","href":"SAT_Words_76_100.html"},{"number":77,"word":"Explicit","partOfSpeech":"","meaning":"Stated clearly and directly, leaving no room for doubt or misunderstanding.","synonyms":["clear","direct","specific"],"antonyms":[],"example":"The science teacher gave explicit instructions for setting up the experiment.","href":"SAT_Words_76_100.html"},{"number":78,"word":"Exonerate","partOfSpeech":"","meaning":"To clear someone of blame or responsibility for a wrongdoing.","synonyms":["clear","absolve","vindicate"],"antonyms":[],"example":"The security video helped exonerate the employee who had been accused of taking the package.","href":"SAT_Words_76_100.html"},{"number":79,"word":"Expedite","partOfSpeech":"","meaning":"To make a process happen more quickly; to speed up.","synonyms":["accelerate","hasten","speed up"],"antonyms":[],"example":"The clerk expedited the application after receiving all the required documents.","href":"SAT_Words_76_100.html"},{"number":80,"word":"Extol","partOfSpeech":"","meaning":"To praise enthusiastically and publicly.","synonyms":["praise","applaud","celebrate"],"antonyms":[],"example":"Critics extolled the film for its careful storytelling and strong performances.","href":"SAT_Words_76_100.html"},{"number":81,"word":"Fallacious","partOfSpeech":"","meaning":"Based on mistaken reasoning or a false belief; logically unsound.","synonyms":["false","misleading","unsound"],"antonyms":[],"example":"The claim that one rainy day disproves climate change is fallacious.","href":"SAT_Words_76_100.html"},{"number":82,"word":"Fastidious","partOfSpeech":"","meaning":"Very careful about accuracy, cleanliness, or small details.","synonyms":["meticulous","precise","careful"],"antonyms":[],"example":"The fastidious editor checked every citation before approving the article.","href":"SAT_Words_76_100.html"},{"number":83,"word":"Feasible","partOfSpeech":"","meaning":"Possible and practical to do successfully.","synonyms":["possible","workable","practical"],"antonyms":[],"example":"After reviewing the budget, the committee decided that the plan was feasible.","href":"SAT_Words_76_100.html"},{"number":84,"word":"Fervent","partOfSpeech":"","meaning":"Showing strong, sincere, and passionate feeling.","synonyms":["passionate","ardent","enthusiastic"],"antonyms":[],"example":"The advocate gave a fervent speech in support of the new community center.","href":"SAT_Words_76_100.html"},{"number":85,"word":"Fluctuate","partOfSpeech":"","meaning":"To change frequently or irregularly, especially between higher and lower amounts.","synonyms":["vary","shift","change"],"antonyms":[],"example":"Fuel prices fluctuate according to changes in supply and demand.","href":"SAT_Words_76_100.html"},{"number":86,"word":"Formidable","partOfSpeech":"","meaning":"Difficult to overcome because of strength, size, skill, or complexity.","synonyms":["intimidating","challenging","daunting"],"antonyms":[],"example":"The team faced a formidable opponent with a strong defense.","href":"SAT_Words_76_100.html"},{"number":87,"word":"Foster","partOfSpeech":"","meaning":"To encourage or help the development of something.","synonyms":["encourage","promote","nurture"],"antonyms":[],"example":"The teacher used group projects to foster cooperation among students.","href":"SAT_Words_76_100.html"},{"number":88,"word":"Fortuitous","partOfSpeech":"","meaning":"Happening by chance, especially in a lucky or helpful way.","synonyms":["lucky","fortunate","accidental"],"antonyms":[],"example":"A fortuitous meeting with a mentor helped the student find an internship.","href":"SAT_Words_76_100.html"},{"number":89,"word":"Frugal","partOfSpeech":"","meaning":"Careful about spending money or using resources; economical.","synonyms":["thrifty","economical","sparing"],"antonyms":[],"example":"By cooking at home and avoiding waste, the family maintained a frugal budget.","href":"SAT_Words_76_100.html"},{"number":90,"word":"Galvanize","partOfSpeech":"","meaning":"To shock or stimulate someone into taking action.","synonyms":["motivate","spur","stimulate"],"antonyms":[],"example":"The sudden power outage galvanized the neighborhood into organizing an emergency plan.","href":"SAT_Words_76_100.html"},{"number":91,"word":"Garrulous","partOfSpeech":"","meaning":"Excessively talkative, especially about unimportant things.","synonyms":["talkative","chatty","loquacious"],"antonyms":[],"example":"The garrulous passenger talked throughout the entire flight.","href":"SAT_Words_76_100.html"},{"number":92,"word":"Genuine","partOfSpeech":"","meaning":"Real, authentic, or sincerely felt.","synonyms":["authentic","real","sincere"],"antonyms":[],"example":"Her genuine interest in the students made her an effective teacher.","href":"SAT_Words_76_100.html"},{"number":93,"word":"Hackneyed","partOfSpeech":"","meaning":"Overused and unoriginal, especially because of being repeated too often.","synonyms":["trite","cliched","stale"],"antonyms":[],"example":"The reviewer called the movie's ending hackneyed because it relied on a familiar cliche.","href":"SAT_Words_76_100.html"},{"number":94,"word":"Haughty","partOfSpeech":"","meaning":"Arrogantly proud and showing that one feels superior to others.","synonyms":["arrogant","proud","snobbish"],"antonyms":[],"example":"His haughty manner made it hard for new employees to approach him.","href":"SAT_Words_76_100.html"},{"number":95,"word":"Hypocrisy","partOfSpeech":"","meaning":"The practice of claiming to have standards or beliefs that one does not actually follow.","synonyms":["double standard","insincerity","pretense"],"antonyms":[],"example":"Students pointed out the hypocrisy of a rule against phones when teachers used phones during meetings.","href":"SAT_Words_76_100.html"},{"number":96,"word":"Hypothesis","partOfSpeech":"","meaning":"A proposed explanation or prediction that can be tested through investigation.","synonyms":["theory","prediction","supposition"],"antonyms":[],"example":"The scientists formed a hypothesis that more sunlight would increase plant growth.","href":"SAT_Words_76_100.html"},{"number":97,"word":"Iconoclast","partOfSpeech":"","meaning":"A person who challenges or rejects widely accepted beliefs, traditions, or practices.","synonyms":["reformer","nonconformist","rebel"],"antonyms":[],"example":"The architect was an iconoclast who rejected traditional building designs.","href":"SAT_Words_76_100.html"},{"number":98,"word":"Imminent","partOfSpeech":"","meaning":"About to happen very soon.","synonyms":["impending","approaching","near"],"antonyms":[],"example":"Dark clouds suggested that a thunderstorm was imminent.","href":"SAT_Words_76_100.html"},{"number":99,"word":"Immutable","partOfSpeech":"","meaning":"Unable to be changed; unchanging.","synonyms":["unchangeable","fixed","permanent"],"antonyms":[],"example":"The author argued that language is not immutable because meanings change over time.","href":"SAT_Words_76_100.html"},{"number":100,"word":"Impartial","partOfSpeech":"","meaning":"Fair and not favoring one person, group, or side over another.","synonyms":["unbiased","fair","neutral"],"antonyms":[],"example":"A judge must remain impartial while listening to both sides of a case.","href":"SAT_Words_76_100.html"},{"number":101,"word":"Deplete","partOfSpeech":"","meaning":"To use up most or all of a supply or resource.","synonyms":["exhaust","consume","drain"],"antonyms":[],"example":"Years of overfishing depleted the lake's supply of trout.","href":"SAT_Words_101_125.html"},{"number":102,"word":"Derive","partOfSpeech":"","meaning":"To obtain or receive something from a source; to trace an origin.","synonyms":["obtain","draw","originate"],"antonyms":[],"example":"Many English words derive from Latin and Greek roots.","href":"SAT_Words_101_125.html"},{"number":103,"word":"Deter","partOfSpeech":"","meaning":"To discourage someone from doing something by making it difficult, risky, or unpleasant.","synonyms":["discourage","prevent","dissuade"],"antonyms":[],"example":"High parking fees may deter visitors from driving downtown.","href":"SAT_Words_101_125.html"},{"number":104,"word":"Deviate","partOfSpeech":"","meaning":"To depart from an accepted path, plan, or standard.","synonyms":["depart","diverge","stray"],"antonyms":[],"example":"The pilot had to deviate from the planned route because of severe weather.","href":"SAT_Words_101_125.html"},{"number":105,"word":"Diligent","partOfSpeech":"","meaning":"Showing steady, careful effort in work or study.","synonyms":["hardworking","conscientious","industrious"],"antonyms":[],"example":"The diligent student reviewed her notes for twenty minutes each evening.","href":"SAT_Words_101_125.html"},{"number":106,"word":"Diminish","partOfSpeech":"","meaning":"To make or become smaller, weaker, or less important.","synonyms":["lessen","reduce","decrease"],"antonyms":[],"example":"The sound of the train gradually diminished as it moved farther away.","href":"SAT_Words_101_125.html"},{"number":107,"word":"Disparity","partOfSpeech":"","meaning":"A noticeable difference, especially an unfair difference between groups or amounts.","synonyms":["inequality","gap","difference"],"antonyms":[],"example":"The report examined the disparity between rural and urban internet access.","href":"SAT_Words_101_125.html"},{"number":108,"word":"Diverse","partOfSpeech":"","meaning":"Showing a great deal of variety; made up of different kinds of people or things.","synonyms":["varied","assorted","multifaceted"],"antonyms":[],"example":"The library's diverse collection includes novels, biographies, and scientific journals.","href":"SAT_Words_101_125.html"},{"number":109,"word":"Dogmatic","partOfSpeech":"","meaning":"Stating opinions as if they are unquestionably true, without considering other views.","synonyms":["assertive","opinionated","rigid"],"antonyms":[],"example":"His dogmatic response left no room for discussion or evidence.","href":"SAT_Words_101_125.html"},{"number":110,"word":"Dubious","partOfSpeech":"","meaning":"Doubtful, uncertain, or not likely to be true.","synonyms":["questionable","doubtful","suspicious"],"antonyms":[],"example":"The editor was dubious about the claim because the article offered no sources.","href":"SAT_Words_101_125.html"},{"number":111,"word":"Eccentric","partOfSpeech":"","meaning":"Unconventional or slightly strange in behavior, appearance, or ideas.","synonyms":["unconventional","odd","quirky"],"antonyms":[],"example":"The eccentric inventor wore mismatched shoes and kept notes on scraps of paper.","href":"SAT_Words_101_125.html"},{"number":112,"word":"Eclectic","partOfSpeech":"","meaning":"Drawing ideas, styles, or methods from a wide range of sources.","synonyms":["varied","wide-ranging","diverse"],"antonyms":[],"example":"Her eclectic playlist included jazz, classical music, and modern pop.","href":"SAT_Words_101_125.html"},{"number":113,"word":"Efficacy","partOfSpeech":"","meaning":"The ability to produce a desired or intended result.","synonyms":["effectiveness","usefulness","power"],"antonyms":[],"example":"Researchers tested the efficacy of the new treatment before recommending it.","href":"SAT_Words_101_125.html"},{"number":114,"word":"Eloquent","partOfSpeech":"","meaning":"Fluent, persuasive, and graceful in speaking or writing.","synonyms":["expressive","articulate","persuasive"],"antonyms":[],"example":"Her eloquent speech persuaded the audience to support the project.","href":"SAT_Words_101_125.html"},{"number":115,"word":"Elusive","partOfSpeech":"","meaning":"Difficult to find, catch, understand, or achieve.","synonyms":["hard-to-find","evasive","slippery"],"antonyms":[],"example":"A complete explanation for the phenomenon remained elusive.","href":"SAT_Words_101_125.html"},{"number":116,"word":"Empirical","partOfSpeech":"","meaning":"Based on observation, measurement, or experiment rather than theory alone.","synonyms":["observational","experimental","evidence-based"],"antonyms":[],"example":"The researchers relied on empirical evidence collected from field observations.","href":"SAT_Words_101_125.html"},{"number":117,"word":"Emulate","partOfSpeech":"","meaning":"To try to match or imitate someone or something admired.","synonyms":["imitate","match","follow"],"antonyms":[],"example":"Young athletes often emulate the training habits of successful players.","href":"SAT_Words_101_125.html"},{"number":118,"word":"Endorse","partOfSpeech":"","meaning":"To publicly approve, support, or recommend.","synonyms":["support","approve","recommend"],"antonyms":[],"example":"Several scientists endorsed the plan to protect the wetlands.","href":"SAT_Words_101_125.html"},{"number":119,"word":"Engender","partOfSpeech":"","meaning":"To cause or give rise to a feeling, situation, or condition.","synonyms":["cause","create","generate"],"antonyms":[],"example":"The coach's honesty engendered trust among the players.","href":"SAT_Words_101_125.html"},{"number":120,"word":"Enigma","partOfSpeech":"","meaning":"A person, thing, or situation that is mysterious and difficult to understand.","synonyms":["mystery","puzzle","riddle"],"antonyms":[],"example":"The ancient inscription remained an enigma until researchers translated it.","href":"SAT_Words_101_125.html"},{"number":121,"word":"Ephemeral","partOfSpeech":"","meaning":"Lasting for a very short time.","synonyms":["temporary","brief","fleeting"],"antonyms":[],"example":"The artist created an ephemeral sculpture from ice that melted by evening.","href":"SAT_Words_101_125.html"},{"number":122,"word":"Equitable","partOfSpeech":"","meaning":"Fair and impartial; treating people fairly according to the circumstances.","synonyms":["fair","just","impartial"],"antonyms":[],"example":"The principal sought an equitable solution that considered every student's needs.","href":"SAT_Words_101_125.html"},{"number":123,"word":"Erratic","partOfSpeech":"","meaning":"Not regular, consistent, or predictable.","synonyms":["unpredictable","irregular","inconsistent"],"antonyms":[],"example":"The car's erratic engine noise made the mechanic suspect a loose connection.","href":"SAT_Words_101_125.html"},{"number":124,"word":"Exacerbate","partOfSpeech":"","meaning":"To make a problem, condition, or feeling worse.","synonyms":["worsen","aggravate","intensify"],"antonyms":[],"example":"Ignoring the leak would only exacerbate the damage to the ceiling.","href":"SAT_Words_101_125.html"},{"number":125,"word":"Exemplary","partOfSpeech":"","meaning":"Serving as an excellent example; outstanding.","synonyms":["excellent","outstanding","model"],"antonyms":[],"example":"Her exemplary research methods made the report easy to trust.","href":"SAT_Words_101_125.html"},{"number":126,"word":"Explicit","partOfSpeech":"","meaning":"Stated clearly and directly, leaving no room for doubt.","synonyms":["clear","definite","specific"],"antonyms":[],"example":"The manual gave explicit instructions for resetting the device.","href":"SAT_Words_126_150.html"},{"number":127,"word":"Exonerate","partOfSpeech":"","meaning":"To officially clear someone from blame or fault.","synonyms":["clear","absolve","vindicate"],"antonyms":[],"example":"The security video helped exonerate the student who had been wrongly accused.","href":"SAT_Words_126_150.html"},{"number":128,"word":"Expedite","partOfSpeech":"","meaning":"To make a process happen more quickly.","synonyms":["accelerate","hasten","speed up"],"antonyms":[],"example":"The school added staff to expedite the registration process.","href":"SAT_Words_126_150.html"},{"number":129,"word":"Extol","partOfSpeech":"","meaning":"To praise enthusiastically.","synonyms":["praise","celebrate","commend"],"antonyms":[],"example":"Critics extolled the film for its imaginative storytelling.","href":"SAT_Words_126_150.html"},{"number":130,"word":"Fallacious","partOfSpeech":"","meaning":"Based on a mistaken belief or faulty reasoning.","synonyms":["misleading","unsound","mistaken"],"antonyms":[],"example":"The argument was fallacious because it treated one example as proof of a general rule.","href":"SAT_Words_126_150.html"},{"number":131,"word":"Fastidious","partOfSpeech":"","meaning":"Very attentive to detail and difficult to satisfy about standards.","synonyms":["meticulous","exacting","careful"],"antonyms":[],"example":"The fastidious editor noticed a missing comma in the final paragraph.","href":"SAT_Words_126_150.html"},{"number":132,"word":"Feasible","partOfSpeech":"","meaning":"Possible and practical to carry out.","synonyms":["possible","practical","workable"],"antonyms":[],"example":"After reviewing the budget, the committee decided that the plan was feasible.","href":"SAT_Words_126_150.html"},{"number":133,"word":"Fervent","partOfSpeech":"","meaning":"Showing intense feeling or enthusiasm.","synonyms":["passionate","ardent","enthusiastic"],"antonyms":[],"example":"The students made a fervent appeal for more art classes.","href":"SAT_Words_126_150.html"},{"number":134,"word":"Fluctuate","partOfSpeech":"","meaning":"To change repeatedly and irregularly.","synonyms":["vary","shift","oscillate"],"antonyms":[],"example":"Fuel prices can fluctuate from one week to the next.","href":"SAT_Words_126_150.html"},{"number":135,"word":"Formidable","partOfSpeech":"","meaning":"Inspiring fear, respect, or awe because of size, strength, or difficulty.","synonyms":["intimidating","powerful","daunting"],"antonyms":[],"example":"The team faced a formidable opponent in the final round.","href":"SAT_Words_126_150.html"},{"number":136,"word":"Foster","partOfSpeech":"","meaning":"To encourage the growth or development of something.","synonyms":["encourage","promote","cultivate"],"antonyms":[],"example":"The program was designed to foster curiosity and creativity.","href":"SAT_Words_126_150.html"},{"number":137,"word":"Fortuitous","partOfSpeech":"","meaning":"Happening by chance, often in a lucky or beneficial way.","synonyms":["lucky","accidental","fortunate"],"antonyms":[],"example":"A fortuitous meeting with a former teacher led to an internship opportunity.","href":"SAT_Words_126_150.html"},{"number":138,"word":"Frugal","partOfSpeech":"","meaning":"Careful about spending money or using resources.","synonyms":["thrifty","economical","sparing"],"antonyms":[],"example":"By packing lunch, the frugal student saved money each week.","href":"SAT_Words_126_150.html"},{"number":139,"word":"Galvanize","partOfSpeech":"","meaning":"To shock or excite people into taking action.","synonyms":["motivate","stimulate","energize"],"antonyms":[],"example":"The report galvanized residents to attend the town meeting.","href":"SAT_Words_126_150.html"},{"number":140,"word":"Garrulous","partOfSpeech":"","meaning":"Excessively talkative, especially about trivial matters.","synonyms":["talkative","chatty","loquacious"],"antonyms":[],"example":"The garrulous passenger spoke throughout the entire flight.","href":"SAT_Words_126_150.html"},{"number":141,"word":"Genuine","partOfSpeech":"","meaning":"Real, authentic, or sincerely felt.","synonyms":["authentic","sincere","real"],"antonyms":[],"example":"Her genuine concern was clear when she stayed late to help.","href":"SAT_Words_126_150.html"},{"number":142,"word":"Hackneyed","partOfSpeech":"","meaning":"Lacking originality because it has been used too often.","synonyms":["cliche","stale","overused"],"antonyms":[],"example":"The reviewer found the movie's ending hackneyed and predictable.","href":"SAT_Words_126_150.html"},{"number":143,"word":"Haughty","partOfSpeech":"","meaning":"Arrogantly superior and disdainful toward others.","synonyms":["arrogant","snobbish","superior"],"antonyms":[],"example":"The haughty customer spoke to the cashier as if no one else mattered.","href":"SAT_Words_126_150.html"},{"number":144,"word":"Hypocrisy","partOfSpeech":"","meaning":"The practice of claiming beliefs or standards that one's behavior does not follow.","synonyms":["pretense","insincerity","double standard"],"antonyms":[],"example":"The article criticized the hypocrisy of demanding conservation while wasting resources.","href":"SAT_Words_126_150.html"},{"number":145,"word":"Hypothesis","partOfSpeech":"","meaning":"A proposed explanation that can be tested through investigation.","synonyms":["theory","proposal","supposition"],"antonyms":[],"example":"The researchers formed a hypothesis before beginning the experiment.","href":"SAT_Words_126_150.html"},{"number":146,"word":"Iconoclast","partOfSpeech":"","meaning":"A person who challenges or rejects widely accepted beliefs or traditions.","synonyms":["rebel","nonconformist","challenger"],"antonyms":[],"example":"The architect was an iconoclast who questioned every standard approach to design.","href":"SAT_Words_126_150.html"},{"number":147,"word":"Imminent","partOfSpeech":"","meaning":"About to happen very soon.","synonyms":["impending","near","forthcoming"],"antonyms":[],"example":"With dark clouds approaching, a storm seemed imminent.","href":"SAT_Words_126_150.html"},{"number":148,"word":"Immutable","partOfSpeech":"","meaning":"Unable to be changed.","synonyms":["unchangeable","fixed","permanent"],"antonyms":[],"example":"The historian explained that social customs are not immutable; they change over time.","href":"SAT_Words_126_150.html"},{"number":149,"word":"Impartial","partOfSpeech":"","meaning":"Fair and not biased toward one side.","synonyms":["fair","neutral","unbiased"],"antonyms":[],"example":"An impartial judge considers the evidence from both sides.","href":"SAT_Words_126_150.html"},{"number":150,"word":"Impede","partOfSpeech":"","meaning":"To delay, obstruct, or make progress difficult.","synonyms":["hinder","obstruct","block"],"antonyms":[],"example":"Road construction may impede traffic during the morning commute.","href":"SAT_Words_126_150.html"},{"number":151,"word":"Implicit","partOfSpeech":"","meaning":"Suggested or understood without being directly stated.","synonyms":["implied","unspoken","indirect"],"antonyms":[],"example":"The professor's implicit message was that revision is part of good writing.","href":"SAT_Words_151_175.html"},{"number":152,"word":"Impetuous","partOfSpeech":"","meaning":"Acting quickly without careful thought about the consequences.","synonyms":["rash","impulsive","hasty"],"antonyms":[],"example":"His impetuous decision to quit the club left him with regrets later.","href":"SAT_Words_151_175.html"},{"number":153,"word":"Inadvertent","partOfSpeech":"","meaning":"Not intentional; accidental.","synonyms":["accidental","unintentional","unintended"],"antonyms":[],"example":"The writer made an inadvertent error when copying the date.","href":"SAT_Words_151_175.html"},{"number":154,"word":"Inclined","partOfSpeech":"","meaning":"Likely or willing to do something; having a tendency toward something.","synonyms":["disposed","likely","prone"],"antonyms":[],"example":"Students who enjoy research may be inclined to join the science club.","href":"SAT_Words_151_175.html"},{"number":155,"word":"Indifferent","partOfSpeech":"","meaning":"Having no particular interest, concern, or sympathy.","synonyms":["unconcerned","apathetic","detached"],"antonyms":[],"example":"The audience seemed indifferent to the speaker's proposal.","href":"SAT_Words_151_175.html"},{"number":156,"word":"Indigenous","partOfSpeech":"","meaning":"Originating or occurring naturally in a particular place.","synonyms":["native","local","original"],"antonyms":[],"example":"The preserve protects indigenous plants that grow nowhere else in the region.","href":"SAT_Words_151_175.html"},{"number":157,"word":"Indispensable","partOfSpeech":"","meaning":"Absolutely necessary or essential.","synonyms":["essential","vital","necessary"],"antonyms":[],"example":"Reliable data is indispensable for making sound decisions.","href":"SAT_Words_151_175.html"},{"number":158,"word":"Indolent","partOfSpeech":"","meaning":"Wanting to avoid activity or effort; lazy.","synonyms":["lazy","idle","sluggish"],"antonyms":[],"example":"The indolent employee avoided tasks that required sustained effort.","href":"SAT_Words_151_175.html"},{"number":159,"word":"Inept","partOfSpeech":"","meaning":"Having little skill or ability; clumsy.","synonyms":["unskilled","incompetent","clumsy"],"antonyms":[],"example":"The inept repair attempt made the leak worse instead of fixing it.","href":"SAT_Words_151_175.html"},{"number":160,"word":"Infamous","partOfSpeech":"","meaning":"Well known for a bad quality, action, or reputation.","synonyms":["notorious","disreputable","ill-famed"],"antonyms":[],"example":"The road is infamous for traffic jams during holiday weekends.","href":"SAT_Words_151_175.html"},{"number":161,"word":"Inherent","partOfSpeech":"","meaning":"Existing as a permanent, essential, or natural part of something.","synonyms":["intrinsic","built-in","essential"],"antonyms":[],"example":"Some risk is inherent in every new business venture.","href":"SAT_Words_151_175.html"},{"number":162,"word":"Innovative","partOfSpeech":"","meaning":"Introducing new ideas, methods, or products.","synonyms":["creative","original","pioneering"],"antonyms":[],"example":"The team developed an innovative way to reduce energy use.","href":"SAT_Words_151_175.html"},{"number":163,"word":"Insidious","partOfSpeech":"","meaning":"Proceeding gradually and subtly in a harmful way.","synonyms":["subtle","stealthy","harmful"],"antonyms":[],"example":"The insidious effects of misinformation can be hard to notice at first.","href":"SAT_Words_151_175.html"},{"number":164,"word":"Integral","partOfSpeech":"","meaning":"Necessary to make a whole complete; essential.","synonyms":["essential","necessary","fundamental"],"antonyms":[],"example":"Regular practice is integral to building confidence in math.","href":"SAT_Words_151_175.html"},{"number":165,"word":"Intrepid","partOfSpeech":"","meaning":"Fearless and willing to face danger or difficulty.","synonyms":["brave","fearless","daring"],"antonyms":[],"example":"The intrepid reporter traveled into the storm to document the rescue effort.","href":"SAT_Words_151_175.html"},{"number":166,"word":"Irascible","partOfSpeech":"","meaning":"Easily angered or irritated.","synonyms":["irritable","short-tempered","testy"],"antonyms":[],"example":"The irascible neighbor complained whenever anyone parked near his driveway.","href":"SAT_Words_151_175.html"},{"number":167,"word":"Lament","partOfSpeech":"","meaning":"To express sorrow, regret, or disappointment about something.","synonyms":["mourn","grieve","regret"],"antonyms":[],"example":"Residents lamented the closing of the neighborhood bookstore.","href":"SAT_Words_151_175.html"},{"number":168,"word":"Lethargic","partOfSpeech":"","meaning":"Lacking energy, enthusiasm, or alertness.","synonyms":["sluggish","tired","inactive"],"antonyms":[],"example":"After the long bus ride, the players felt lethargic during practice.","href":"SAT_Words_151_175.html"},{"number":169,"word":"Magnanimous","partOfSpeech":"","meaning":"Generous and forgiving, especially toward a rival or someone less powerful.","synonyms":["generous","forgiving","noble"],"antonyms":[],"example":"After winning the debate, she was magnanimous and praised her opponent's strong points.","href":"SAT_Words_151_175.html"},{"number":170,"word":"Malleable","partOfSpeech":"","meaning":"Easily shaped, molded, or influenced.","synonyms":["flexible","pliable","adaptable"],"antonyms":[],"example":"Copper is malleable enough to be formed into thin wires.","href":"SAT_Words_151_175.html"},{"number":171,"word":"Meager","partOfSpeech":"","meaning":"Lacking in quantity or quality; too small or insufficient.","synonyms":["scant","sparse","insufficient"],"antonyms":[],"example":"The shelter had only a meager supply of blankets after the storm.","href":"SAT_Words_151_175.html"},{"number":172,"word":"Mercurial","partOfSpeech":"","meaning":"Subject to sudden or unpredictable changes in mood or behavior.","synonyms":["volatile","unpredictable","changeable"],"antonyms":[],"example":"The mercurial artist could be cheerful one moment and frustrated the next.","href":"SAT_Words_151_175.html"},{"number":173,"word":"Methodical","partOfSpeech":"","meaning":"Done in an orderly, systematic way.","synonyms":["systematic","orderly","organized"],"antonyms":[],"example":"The methodical researcher labeled every sample before beginning the test.","href":"SAT_Words_151_175.html"},{"number":174,"word":"Mundane","partOfSpeech":"","meaning":"Lacking interest or excitement; ordinary.","synonyms":["ordinary","routine","commonplace"],"antonyms":[],"example":"Sorting old files was a mundane task, but it made the office more organized.","href":"SAT_Words_151_175.html"},{"number":175,"word":"Negligible","partOfSpeech":"","meaning":"So small or unimportant that it is not worth considering.","synonyms":["minor","insignificant","trivial"],"antonyms":[],"example":"The difference in cost was negligible compared with the overall budget.","href":"SAT_Words_151_175.html"},{"number":176,"word":"Novel","partOfSpeech":"","meaning":"New, original, and unlike anything seen before.","synonyms":["original","new","innovative"],"antonyms":[],"example":"The engineer proposed a novel approach to collecting solar energy.","href":"SAT_Words_176_200.html"},{"number":177,"word":"Nuance","partOfSpeech":"","meaning":"A subtle difference in meaning, expression, or tone.","synonyms":["subtlety","distinction","shade"],"antonyms":[],"example":"The translator explained the nuance between the two similar words.","href":"SAT_Words_176_200.html"},{"number":178,"word":"Objective","partOfSpeech":"","meaning":"Not influenced by personal feelings or opinions; a goal to be achieved.","synonyms":["unbiased","neutral","fair"],"antonyms":[],"example":"The reviewer tried to give an objective assessment of the two proposals.","href":"SAT_Words_176_200.html"},{"number":179,"word":"Obsolete","partOfSpeech":"","meaning":"No longer used or useful because something newer has replaced it.","synonyms":["outdated","old-fashioned","superseded"],"antonyms":[],"example":"Many people consider typewriters obsolete now that computers are common.","href":"SAT_Words_176_200.html"},{"number":180,"word":"Obstinate","partOfSpeech":"","meaning":"Stubbornly refusing to change an opinion, course of action, or behavior.","synonyms":["stubborn","inflexible","headstrong"],"antonyms":[],"example":"The obstinate child refused to wear a coat despite the cold weather.","href":"SAT_Words_176_200.html"},{"number":181,"word":"Opaque","partOfSpeech":"","meaning":"Not able to be seen through; difficult to understand.","synonyms":["unclear","obscure","nontransparent"],"antonyms":[],"example":"The report's opaque language made the policy difficult for residents to understand.","href":"SAT_Words_176_200.html"},{"number":182,"word":"Optimal","partOfSpeech":"","meaning":"Best or most favorable under particular conditions.","synonyms":["best","ideal","most favorable"],"antonyms":[],"example":"The gardener chose the optimal time to plant seeds based on the weather forecast.","href":"SAT_Words_176_200.html"},{"number":183,"word":"Ostentatious","partOfSpeech":"","meaning":"Designed to attract attention or impress others in a showy way.","synonyms":["showy","flashy","pretentious"],"antonyms":[],"example":"The actor arrived in an ostentatious car covered with bright decorations.","href":"SAT_Words_176_200.html"},{"number":184,"word":"Paradox","partOfSpeech":"","meaning":"A statement or situation that seems contradictory but may reveal a truth.","synonyms":["contradiction","puzzle","irony"],"antonyms":[],"example":"It is a paradox that saving time with technology can sometimes make people feel busier.","href":"SAT_Words_176_200.html"},{"number":185,"word":"Parsimonious","partOfSpeech":"","meaning":"Unwilling to spend money or use resources; excessively frugal.","synonyms":["stingy","miserly","tightfisted"],"antonyms":[],"example":"The parsimonious owner refused to replace broken equipment even when repairs cost more.","href":"SAT_Words_176_200.html"},{"number":186,"word":"Perceive","partOfSpeech":"","meaning":"To become aware of, notice, or understand through the senses or mind.","synonyms":["notice","observe","recognize"],"antonyms":[],"example":"People may perceive the same event differently depending on their experiences.","href":"SAT_Words_176_200.html"},{"number":187,"word":"Perennial","partOfSpeech":"","meaning":"Lasting for a long time or recurring every year.","synonyms":["recurring","enduring","lasting"],"antonyms":[],"example":"Water conservation is a perennial concern in dry regions.","href":"SAT_Words_176_200.html"},{"number":188,"word":"Perpetual","partOfSpeech":"","meaning":"Never ending or changing; occurring repeatedly.","synonyms":["constant","continual","endless"],"antonyms":[],"example":"The machine's perpetual humming made it hard to concentrate.","href":"SAT_Words_176_200.html"},{"number":189,"word":"Pertinent","partOfSpeech":"","meaning":"Relevant and directly related to the matter being considered.","synonyms":["relevant","applicable","related"],"antonyms":[],"example":"The librarian selected only pertinent sources for the student's research question.","href":"SAT_Words_176_200.html"},{"number":190,"word":"Pervasive","partOfSpeech":"","meaning":"Spreading widely throughout an area, group, or system.","synonyms":["widespread","prevalent","extensive"],"antonyms":[],"example":"Smartphones have become pervasive in daily life.","href":"SAT_Words_176_200.html"},{"number":191,"word":"Pious","partOfSpeech":"","meaning":"Devoutly religious; sometimes, showing a self-righteous display of goodness.","synonyms":["devout","reverent","religious"],"antonyms":[],"example":"The pious family attended services regularly and volunteered in the community.","href":"SAT_Words_176_200.html"},{"number":192,"word":"Placate","partOfSpeech":"","meaning":"To make someone less angry or hostile by giving in or calming them.","synonyms":["appease","pacify","soothe"],"antonyms":[],"example":"The company offered refunds to placate dissatisfied customers.","href":"SAT_Words_176_200.html"},{"number":193,"word":"Plausible","partOfSpeech":"","meaning":"Seeming reasonable or likely to be true.","synonyms":["believable","reasonable","credible"],"antonyms":[],"example":"Her explanation was plausible because it fit the evidence.","href":"SAT_Words_176_200.html"},{"number":194,"word":"Poignant","partOfSpeech":"","meaning":"Evoking a keen sense of sadness, regret, or emotional depth.","synonyms":["moving","touching","emotional"],"antonyms":[],"example":"The final letter in the novel was poignant because it revealed how much the family had lost.","href":"SAT_Words_176_200.html"},{"number":195,"word":"Pragmatic","partOfSpeech":"","meaning":"Dealing with problems in a practical and realistic way.","synonyms":["practical","realistic","sensible"],"antonyms":[],"example":"Rather than argue about perfect solutions, the group took a pragmatic approach.","href":"SAT_Words_176_200.html"},{"number":196,"word":"Precarious","partOfSpeech":"","meaning":"Not securely held or stable; dangerously uncertain.","synonyms":["unstable","risky","uncertain"],"antonyms":[],"example":"The ladder was in a precarious position on the uneven ground.","href":"SAT_Words_176_200.html"},{"number":197,"word":"Precede","partOfSpeech":"","meaning":"To come before something in time, order, or position.","synonyms":["come before","lead","predate"],"antonyms":[],"example":"A short introduction preceded the main presentation.","href":"SAT_Words_176_200.html"},{"number":198,"word":"Precise","partOfSpeech":"","meaning":"Marked by exactness, accuracy, and careful attention to detail.","synonyms":["exact","accurate","specific"],"antonyms":[],"example":"The scientist recorded the precise temperature at each stage of the experiment.","href":"SAT_Words_176_200.html"},{"number":199,"word":"Predominant","partOfSpeech":"","meaning":"Present as the strongest, most common, or most important element.","synonyms":["main","dominant","prevailing"],"antonyms":[],"example":"Blue was the predominant color in the artist's landscape painting.","href":"SAT_Words_176_200.html"},{"number":200,"word":"Proficient","partOfSpeech":"","meaning":"Competent or skilled at doing something.","synonyms":["skilled","capable","accomplished"],"antonyms":[],"example":"After months of practice, Lena became proficient at using the new software.","href":"SAT_Words_176_200.html"},{"number":201,"word":"Prolific","partOfSpeech":"","meaning":"Producing many works, results, or ideas in a short period of time.","synonyms":["productive","fruitful","abundant"],"antonyms":[],"example":"The prolific author published three novels and dozens of essays.","href":"SAT_Words_201_225.html"},{"number":202,"word":"Prompt","partOfSpeech":"","meaning":"To cause, bring about, or encourage an action or response.","synonyms":["cause","provoke","stimulate"],"antonyms":[],"example":"The unexpected result prompted the researchers to repeat the experiment.","href":"SAT_Words_201_225.html"},{"number":203,"word":"Propensity","partOfSpeech":"","meaning":"A natural tendency or inclination toward a particular behavior.","synonyms":["tendency","inclination","disposition"],"antonyms":[],"example":"Her propensity for careful planning made her an effective project leader.","href":"SAT_Words_201_225.html"},{"number":204,"word":"Prudent","partOfSpeech":"","meaning":"Acting with care and good judgment, especially about the future.","synonyms":["wise","cautious","sensible"],"antonyms":[],"example":"It was prudent to save a copy of the project before making major changes.","href":"SAT_Words_201_225.html"},{"number":205,"word":"Ravenous","partOfSpeech":"","meaning":"Extremely hungry; showing a very strong desire for something.","synonyms":["famished","starving","voracious"],"antonyms":[],"example":"After the long practice, the players were ravenous and ate quickly.","href":"SAT_Words_201_225.html"},{"number":206,"word":"Reconcile","partOfSpeech":"","meaning":"To restore friendly relations; to bring two ideas or facts into agreement.","synonyms":["resolve","harmonize","reunite"],"antonyms":[],"example":"The two friends reconciled after discussing the misunderstanding honestly.","href":"SAT_Words_201_225.html"},{"number":207,"word":"Redundant","partOfSpeech":"","meaning":"Unnecessary because it is repeated or already included.","synonyms":["repetitive","unnecessary","superfluous"],"antonyms":[],"example":"The editor removed redundant sentences that repeated the same point.","href":"SAT_Words_201_225.html"},{"number":208,"word":"Refute","partOfSpeech":"","meaning":"To prove a statement, argument, or claim to be wrong.","synonyms":["disprove","contradict","rebut"],"antonyms":[],"example":"The new evidence refuted the rumor that the bridge was unsafe.","href":"SAT_Words_201_225.html"},{"number":209,"word":"Reinforce","partOfSpeech":"","meaning":"To strengthen, support, or make an idea more convincing.","synonyms":["strengthen","support","bolster"],"antonyms":[],"example":"Several examples reinforced the author's main argument.","href":"SAT_Words_201_225.html"},{"number":210,"word":"Reluctant","partOfSpeech":"","meaning":"Unwilling or hesitant to do something.","synonyms":["hesitant","unwilling","resistant"],"antonyms":[],"example":"Maya was reluctant to speak because she had not finished her research.","href":"SAT_Words_201_225.html"},{"number":211,"word":"Resilient","partOfSpeech":"","meaning":"Able to recover quickly after difficulties or setbacks.","synonyms":["adaptable","hardy","strong"],"antonyms":[],"example":"The resilient community rebuilt after the storm damaged several homes.","href":"SAT_Words_201_225.html"},{"number":212,"word":"Revere","partOfSpeech":"","meaning":"To feel deep respect and admiration for someone or something.","synonyms":["admire","honor","venerate"],"antonyms":[],"example":"Many students revere the teacher who inspired them to pursue science.","href":"SAT_Words_201_225.html"},{"number":213,"word":"Robust","partOfSpeech":"","meaning":"Strong, healthy, and able to perform well under difficult conditions.","synonyms":["strong","sturdy","vigorous"],"antonyms":[],"example":"The engineers designed a robust system that could handle heavy use.","href":"SAT_Words_201_225.html"},{"number":214,"word":"Sagacious","partOfSpeech":"","meaning":"Showing wise judgment and keen understanding.","synonyms":["wise","shrewd","discerning"],"antonyms":[],"example":"The sagacious adviser noticed risks that others had overlooked.","href":"SAT_Words_201_225.html"},{"number":215,"word":"Salient","partOfSpeech":"","meaning":"Most noticeable, important, or relevant.","synonyms":["important","prominent","notable"],"antonyms":[],"example":"The report highlighted the salient findings from the survey.","href":"SAT_Words_201_225.html"},{"number":216,"word":"Satiate","partOfSpeech":"","meaning":"To satisfy completely, especially a hunger, desire, or need.","synonyms":["satisfy","fulfill","appease"],"antonyms":[],"example":"The large meal satiated the hungry travelers.","href":"SAT_Words_201_225.html"},{"number":217,"word":"Scrutinize","partOfSpeech":"","meaning":"To examine something very carefully and closely.","synonyms":["inspect","examine","analyze"],"antonyms":[],"example":"The scientists scrutinized the data before publishing their conclusions.","href":"SAT_Words_201_225.html"},{"number":218,"word":"Serene","partOfSpeech":"","meaning":"Calm, peaceful, and untroubled.","synonyms":["calm","peaceful","tranquil"],"antonyms":[],"example":"The lake looked serene in the early morning light.","href":"SAT_Words_201_225.html"},{"number":219,"word":"Skeptical","partOfSpeech":"","meaning":"Doubtful; not easily convinced without evidence.","synonyms":["doubtful","questioning","suspicious"],"antonyms":[],"example":"The audience was skeptical of the advertisement's dramatic claims.","href":"SAT_Words_201_225.html"},{"number":220,"word":"Sparse","partOfSpeech":"","meaning":"Thinly scattered or present in small amounts.","synonyms":["scant","thin","limited"],"antonyms":[],"example":"Sparse vegetation covered the dry hillside.","href":"SAT_Words_201_225.html"},{"number":221,"word":"Sporadic","partOfSpeech":"","meaning":"Occurring at irregular intervals; not consistent.","synonyms":["occasional","irregular","intermittent"],"antonyms":[],"example":"The signal was sporadic, cutting out several times during the call.","href":"SAT_Words_201_225.html"},{"number":222,"word":"Stagnant","partOfSpeech":"","meaning":"Not moving, changing, or developing; inactive.","synonyms":["motionless","inactive","stale"],"antonyms":[],"example":"Without fresh water, the pond became stagnant.","href":"SAT_Words_201_225.html"},{"number":223,"word":"Stoic","partOfSpeech":"","meaning":"Enduring hardship without showing much emotion or complaint.","synonyms":["unemotional","composed","enduring"],"antonyms":[],"example":"She remained stoic after receiving disappointing news.","href":"SAT_Words_201_225.html"},{"number":224,"word":"Substantial","partOfSpeech":"","meaning":"Large in amount, size, importance, or value.","synonyms":["considerable","significant","sizable"],"antonyms":[],"example":"The scholarship provided substantial financial support for tuition.","href":"SAT_Words_201_225.html"},{"number":225,"word":"Succinct","partOfSpeech":"","meaning":"Brief and clearly expressed.","synonyms":["concise","brief","compact"],"antonyms":[],"example":"The student gave a succinct summary of the article's main claim.","href":"SAT_Words_201_225.html"},{"number":226,"word":"Sufficient","partOfSpeech":"","meaning":"Enough for a particular purpose or need.","synonyms":["adequate","enough","ample"],"antonyms":[],"example":"The team collected sufficient evidence to support its conclusion.","href":"SAT_Words_226_250.html"},{"number":227,"word":"Superficial","partOfSpeech":"","meaning":"Concerned only with the surface or obvious features; not deep or thorough.","synonyms":["shallow","cursory","surface-level"],"antonyms":[],"example":"The report offered a superficial explanation but did not analyze the causes.","href":"SAT_Words_226_250.html"},{"number":228,"word":"Sustain","partOfSpeech":"","meaning":"To maintain, support, or keep something going over time.","synonyms":["maintain","support","preserve"],"antonyms":[],"example":"The organization needs donations to sustain its tutoring program.","href":"SAT_Words_226_250.html"},{"number":229,"word":"Tangible","partOfSpeech":"","meaning":"Real and concrete; able to be seen, touched, or clearly measured.","synonyms":["concrete","real","measurable"],"antonyms":[],"example":"The new policy produced tangible improvements in classroom safety.","href":"SAT_Words_226_250.html"},{"number":230,"word":"Tentative","partOfSpeech":"","meaning":"Not certain or final; done with hesitation.","synonyms":["uncertain","provisional","hesitant"],"antonyms":[],"example":"The team made tentative plans because the weather forecast was uncertain.","href":"SAT_Words_226_250.html"},{"number":231,"word":"Tenacious","partOfSpeech":"","meaning":"Not giving up easily; holding firmly to a goal or belief.","synonyms":["persistent","determined","steadfast"],"antonyms":[],"example":"The tenacious student kept revising the essay until it was clear.","href":"SAT_Words_226_250.html"},{"number":232,"word":"Thorough","partOfSpeech":"","meaning":"Complete, careful, and detailed.","synonyms":["complete","comprehensive","detailed"],"antonyms":[],"example":"The inspector performed a thorough review of the building.","href":"SAT_Words_226_250.html"},{"number":233,"word":"Transient","partOfSpeech":"","meaning":"Lasting only a short time; temporary.","synonyms":["temporary","brief","short-lived"],"antonyms":[],"example":"The power outage was transient and lasted only a few minutes.","href":"SAT_Words_226_250.html"},{"number":234,"word":"Transparent","partOfSpeech":"","meaning":"Easy to see through; open and easy to understand.","synonyms":["open","clear","straightforward"],"antonyms":[],"example":"The school used a transparent process for selecting student leaders.","href":"SAT_Words_226_250.html"},{"number":235,"word":"Ubiquitous","partOfSpeech":"","meaning":"Present or appearing everywhere.","synonyms":["widespread","universal","omnipresent"],"antonyms":[],"example":"Smartphones have become ubiquitous in modern daily life.","href":"SAT_Words_226_250.html"},{"number":236,"word":"Unanimous","partOfSpeech":"","meaning":"Fully in agreement; supported by everyone involved.","synonyms":["united","agreed","uniform"],"antonyms":[],"example":"The committee reached a unanimous decision to approve the proposal.","href":"SAT_Words_226_250.html"},{"number":237,"word":"Undermine","partOfSpeech":"","meaning":"To weaken gradually or damage the strength, confidence, or success of something.","synonyms":["weaken","erode","sabotage"],"antonyms":[],"example":"Repeated errors undermined the public's trust in the report.","href":"SAT_Words_226_250.html"},{"number":238,"word":"Validate","partOfSpeech":"","meaning":"To confirm that something is accurate, sound, or acceptable.","synonyms":["confirm","verify","support"],"antonyms":[],"example":"The experiment validated the researchers' earlier prediction.","href":"SAT_Words_226_250.html"},{"number":239,"word":"Venerate","partOfSpeech":"","meaning":"To regard with great respect and reverence.","synonyms":["honor","revere","respect"],"antonyms":[],"example":"The town continues to venerate the founder of its public library.","href":"SAT_Words_226_250.html"},{"number":240,"word":"Viable","partOfSpeech":"","meaning":"Capable of working successfully; practical and likely to succeed.","synonyms":["workable","feasible","practical"],"antonyms":[],"example":"After testing several ideas, the engineers found a viable solution.","href":"SAT_Words_226_250.html"},{"number":241,"word":"Vigilant","partOfSpeech":"","meaning":"Carefully watchful and alert to possible danger or problems.","synonyms":["alert","watchful","attentive"],"antonyms":[],"example":"The lifeguard remained vigilant while children played in the pool.","href":"SAT_Words_226_250.html"},{"number":242,"word":"Virtually","partOfSpeech":"","meaning":"Almost completely; for all practical purposes.","synonyms":["nearly","almost","practically"],"antonyms":[],"example":"The new road made the two towns virtually connected.","href":"SAT_Words_226_250.html"},{"number":243,"word":"Volatile","partOfSpeech":"","meaning":"Likely to change suddenly and unpredictably; unstable.","synonyms":["unstable","unpredictable","changeable"],"antonyms":[],"example":"The volatile market rose one day and fell sharply the next.","href":"SAT_Words_226_250.html"},{"number":244,"word":"Widespread","partOfSpeech":"","meaning":"Existing or happening over a large area or among many people.","synonyms":["extensive","prevalent","broad"],"antonyms":[],"example":"The announcement received widespread support from local residents.","href":"SAT_Words_226_250.html"},{"number":245,"word":"Yield","partOfSpeech":"","meaning":"To produce, provide, or result in something.","synonyms":["produce","generate","provide"],"antonyms":[],"example":"The farm yielded a large crop after a season of steady rain.","href":"SAT_Words_226_250.html"},{"number":246,"word":"Adverse","partOfSpeech":"","meaning":"Harmful, unfavorable, or working against success.","synonyms":["unfavorable","harmful","negative"],"antonyms":[],"example":"Adverse weather conditions delayed the flight.","href":"SAT_Words_226_250.html"},{"number":247,"word":"Advocate","partOfSpeech":"","meaning":"To publicly support a cause or proposal; a person who supports a cause.","synonyms":["support","promote","champion"],"antonyms":[],"example":"Several students advocate for longer library hours during exam week.","href":"SAT_Words_226_250.html"},{"number":248,"word":"Aggregate","partOfSpeech":"","meaning":"A total formed by combining parts; to collect or combine into a total.","synonyms":["total","sum","combined amount"],"antonyms":[],"example":"The aggregate score included points from every section of the competition.","href":"SAT_Words_226_250.html"},{"number":249,"word":"Altruistic","partOfSpeech":"","meaning":"Showing unselfish concern for the well-being of others.","synonyms":["selfless","generous","charitable"],"antonyms":[],"example":"Her altruistic decision to volunteer helped many families.","href":"SAT_Words_226_250.html"},{"number":250,"word":"Analogous","partOfSpeech":"","meaning":"Similar in important ways, allowing comparison.","synonyms":["similar","comparable","parallel"],"antonyms":[],"example":"The teacher used an analogous example to explain the difficult concept.","href":"SAT_Words_226_250.html"},{"number":251,"word":"Anticipate","partOfSpeech":"","meaning":"To expect or prepare for something before it happens.","synonyms":["expect","foresee","predict"],"antonyms":[],"example":"The city anticipated heavy traffic and added extra buses for the festival.","href":"SAT_Words_251_275.html"},{"number":252,"word":"Avert","partOfSpeech":"","meaning":"To prevent or turn away something harmful or unwanted.","synonyms":["prevent","avoid","forestall"],"antonyms":[],"example":"The early warning system helped avert a serious accident.","href":"SAT_Words_251_275.html"},{"number":253,"word":"Banal","partOfSpeech":"","meaning":"So common or predictable that it lacks originality or interest.","synonyms":["trite","ordinary","cliche"],"antonyms":[],"example":"The reviewer called the movie's ending banal because it followed a familiar pattern.","href":"SAT_Words_251_275.html"},{"number":254,"word":"Cautious","partOfSpeech":"","meaning":"Careful to avoid danger, mistakes, or unnecessary risk.","synonyms":["careful","wary","prudent"],"antonyms":[],"example":"The cautious driver slowed down on the icy road.","href":"SAT_Words_251_275.html"},{"number":255,"word":"Circumspect","partOfSpeech":"","meaning":"Careful to consider all possible consequences before acting or speaking.","synonyms":["prudent","cautious","discreet"],"antonyms":[],"example":"The lawyer was circumspect when answering questions from reporters.","href":"SAT_Words_251_275.html"},{"number":256,"word":"Cite","partOfSpeech":"","meaning":"To mention or refer to a source as evidence or authority.","synonyms":["reference","quote","mention"],"antonyms":[],"example":"The student cited three reliable studies in her research paper.","href":"SAT_Words_251_275.html"},{"number":257,"word":"Collate","partOfSpeech":"","meaning":"To collect, arrange, and compare information in an organized way.","synonyms":["compile","gather","organize"],"antonyms":[],"example":"The assistant collated survey responses before the meeting.","href":"SAT_Words_251_275.html"},{"number":258,"word":"Compatible","partOfSpeech":"","meaning":"Able to exist, work, or function together without conflict.","synonyms":["consistent","suitable","harmonious"],"antonyms":[],"example":"The new software is compatible with older computers.","href":"SAT_Words_251_275.html"},{"number":259,"word":"Complement","partOfSpeech":"","meaning":"To complete or enhance something by adding a suitable feature.","synonyms":["enhance","complete","supplement"],"antonyms":[],"example":"The chart complements the article by making the trend easier to see.","href":"SAT_Words_251_275.html"},{"number":260,"word":"Comprise","partOfSpeech":"","meaning":"To consist of or be made up of.","synonyms":["consist of","include","contain"],"antonyms":[],"example":"The committee comprises teachers, students, and parents.","href":"SAT_Words_251_275.html"},{"number":261,"word":"Conciliate","partOfSpeech":"","meaning":"To calm someone who is angry or to bring opposing sides toward agreement.","synonyms":["appease","reconcile","pacify"],"antonyms":[],"example":"The mediator tried to conciliate the two groups after the dispute.","href":"SAT_Words_251_275.html"},{"number":262,"word":"Constrain","partOfSpeech":"","meaning":"To limit, restrict, or force something to stay within bounds.","synonyms":["restrict","limit","confine"],"antonyms":[],"example":"A limited budget constrained the number of projects the club could fund.","href":"SAT_Words_251_275.html"},{"number":263,"word":"Contingent","partOfSpeech":"","meaning":"Dependent on something else happening first.","synonyms":["dependent","conditional","subject to"],"antonyms":[],"example":"The outdoor concert is contingent on favorable weather.","href":"SAT_Words_251_275.html"},{"number":264,"word":"Conundrum","partOfSpeech":"","meaning":"A confusing and difficult problem or question.","synonyms":["puzzle","dilemma","problem"],"antonyms":[],"example":"Finding enough parking near the stadium remains a conundrum for city planners.","href":"SAT_Words_251_275.html"},{"number":265,"word":"Cumulative","partOfSpeech":"","meaning":"Increasing or growing by adding successive parts over time.","synonyms":["combined","accumulated","growing"],"antonyms":[],"example":"The cumulative effect of small expenses made the trip more costly than expected.","href":"SAT_Words_251_275.html"},{"number":266,"word":"Deference","partOfSpeech":"","meaning":"Respectful submission to another person's judgment, authority, or position.","synonyms":["respect","regard","submission"],"antonyms":[],"example":"Out of deference to the expert, the group considered her recommendation carefully.","href":"SAT_Words_251_275.html"},{"number":267,"word":"Diffuse","partOfSpeech":"","meaning":"To spread widely; spread out rather than concentrated.","synonyms":["spread","disperse","scatter"],"antonyms":[],"example":"The speaker used simple diagrams to diffuse complex information throughout the presentation.","href":"SAT_Words_251_275.html"},{"number":268,"word":"Discrete","partOfSpeech":"","meaning":"Separate and distinct; individual rather than continuous.","synonyms":["separate","distinct","individual"],"antonyms":[],"example":"The report separates the budget into discrete categories such as travel and supplies.","href":"SAT_Words_251_275.html"},{"number":269,"word":"Displace","partOfSpeech":"","meaning":"To force someone or something out of its usual position or place.","synonyms":["remove","relocate","uproot"],"antonyms":[],"example":"The flood displaced hundreds of residents from their homes.","href":"SAT_Words_251_275.html"},{"number":270,"word":"Dispute","partOfSpeech":"","meaning":"A disagreement or argument; to question the truth or validity of something.","synonyms":["argue","challenge","contest"],"antonyms":[],"example":"The researchers disputed the claim because the evidence was incomplete.","href":"SAT_Words_251_275.html"},{"number":271,"word":"Disseminate","partOfSpeech":"","meaning":"To spread information, ideas, or knowledge widely.","synonyms":["distribute","spread","circulate"],"antonyms":[],"example":"The museum used social media to disseminate information about the exhibit.","href":"SAT_Words_251_275.html"},{"number":272,"word":"Emerge","partOfSpeech":"","meaning":"To come into view, become known, or arise.","synonyms":["appear","arise","develop"],"antonyms":[],"example":"A clear pattern emerged after the team examined the data.","href":"SAT_Words_251_275.html"},{"number":273,"word":"Entail","partOfSpeech":"","meaning":"To involve or require as a necessary part or consequence.","synonyms":["involve","require","necessitate"],"antonyms":[],"example":"Completing the project will entail several weeks of research.","href":"SAT_Words_251_275.html"},{"number":274,"word":"Eradicate","partOfSpeech":"","meaning":"To destroy or eliminate completely.","synonyms":["eliminate","destroy","wipe out"],"antonyms":[],"example":"Public health programs helped eradicate smallpox in many parts of the world.","href":"SAT_Words_251_275.html"},{"number":275,"word":"Erode","partOfSpeech":"","meaning":"To gradually wear away, weaken, or destroy.","synonyms":["wear away","weaken","deteriorate"],"antonyms":[],"example":"Years of heavy rain eroded the riverbank.","href":"SAT_Words_251_275.html"},{"number":276,"word":"Expend","partOfSpeech":"","meaning":"To spend or use resources such as money, time, or effort.","synonyms":["spend","use","devote"],"antonyms":[],"example":"The team expended considerable effort preparing for the competition.","href":"SAT_Words_276_300.html"},{"number":277,"word":"Extrapolate","partOfSpeech":"","meaning":"To estimate or infer something beyond known facts by using existing information.","synonyms":["infer","project","estimate"],"antonyms":[],"example":"The researchers extrapolated future population growth from current trends.","href":"SAT_Words_276_300.html"},{"number":278,"word":"Frivolous","partOfSpeech":"","meaning":"Not serious or useful; lacking a sensible purpose.","synonyms":["trivial","silly","unserious"],"antonyms":[],"example":"The judge dismissed the lawsuit as frivolous because it had no valid basis.","href":"SAT_Words_276_300.html"},{"number":279,"word":"Imperative","partOfSpeech":"","meaning":"Absolutely necessary or extremely important.","synonyms":["essential","crucial","urgent"],"antonyms":[],"example":"It is imperative that the team back up the files before updating the system.","href":"SAT_Words_276_300.html"},{"number":280,"word":"Incisive","partOfSpeech":"","meaning":"Clear, direct, and intelligently analytical.","synonyms":["sharp","perceptive","penetrating"],"antonyms":[],"example":"The columnist's incisive analysis identified the central problem immediately.","href":"SAT_Words_276_300.html"},{"number":281,"word":"Incongruous","partOfSpeech":"","meaning":"Not in harmony or not fitting well with the surrounding situation.","synonyms":["inappropriate","mismatched","out of place"],"antonyms":[],"example":"The modern sculpture looked incongruous in the historic courtroom.","href":"SAT_Words_276_300.html"},{"number":282,"word":"Induce","partOfSpeech":"","meaning":"To cause, bring about, or persuade someone to do something.","synonyms":["cause","persuade","prompt"],"antonyms":[],"example":"The bright light can induce a headache in some people.","href":"SAT_Words_276_300.html"},{"number":283,"word":"Inhibit","partOfSpeech":"","meaning":"To hinder, restrain, or prevent an action or process.","synonyms":["restrain","hinder","prevent"],"antonyms":[],"example":"Fear of making mistakes can inhibit students from asking questions.","href":"SAT_Words_276_300.html"},{"number":284,"word":"Inordinate","partOfSpeech":"","meaning":"Excessive; much more than is reasonable or usual.","synonyms":["excessive","unreasonable","undue"],"antonyms":[],"example":"The project required an inordinate amount of time for a simple task.","href":"SAT_Words_276_300.html"},{"number":285,"word":"Intuitive","partOfSpeech":"","meaning":"Easy to understand or use without needing detailed instruction; based on instinctive understanding.","synonyms":["instinctive","natural","easy-to-use"],"antonyms":[],"example":"The app's intuitive design allowed new users to navigate it quickly.","href":"SAT_Words_276_300.html"},{"number":286,"word":"Ironic","partOfSpeech":"","meaning":"Characterized by a result that is opposite of what is expected or intended.","synonyms":["unexpected","contradictory","paradoxical"],"antonyms":[],"example":"It was ironic that the fire station needed help after a small fire damaged its kitchen.","href":"SAT_Words_276_300.html"},{"number":287,"word":"Judicious","partOfSpeech":"","meaning":"Showing good judgment and careful thought.","synonyms":["wise","sensible","prudent"],"antonyms":[],"example":"The principal made a judicious decision after hearing from teachers and students.","href":"SAT_Words_276_300.html"},{"number":288,"word":"Legitimate","partOfSpeech":"","meaning":"Lawful, valid, or reasonable.","synonyms":["valid","lawful","genuine"],"antonyms":[],"example":"The committee considered the student's concern legitimate and investigated it.","href":"SAT_Words_276_300.html"},{"number":289,"word":"Marginal","partOfSpeech":"","meaning":"Small in amount or importance; close to the edge or limit.","synonyms":["slight","minor","limited"],"antonyms":[],"example":"The new plan produced only marginal improvements in attendance.","href":"SAT_Words_276_300.html"},{"number":290,"word":"Moderate","partOfSpeech":"","meaning":"Not extreme; reasonable in amount or degree.","synonyms":["reasonable","mild","balanced"],"antonyms":[],"example":"The region has a moderate climate with neither severe heat nor severe cold.","href":"SAT_Words_276_300.html"},{"number":291,"word":"Nominal","partOfSpeech":"","meaning":"Very small compared with the real value or cost; existing mainly in name.","synonyms":["token","minimal","slight"],"antonyms":[],"example":"The museum charged only a nominal fee to make admission affordable.","href":"SAT_Words_276_300.html"},{"number":292,"word":"Ostensibly","partOfSpeech":"","meaning":"Apparently or supposedly, although the true reason may be different.","synonyms":["apparently","supposedly","seemingly"],"antonyms":[],"example":"The meeting was ostensibly about budgets, but it became a debate about priorities.","href":"SAT_Words_276_300.html"},{"number":293,"word":"Parity","partOfSpeech":"","meaning":"Equality or equivalence, especially in status, amount, or value.","synonyms":["equality","equivalence","balance"],"antonyms":[],"example":"The study examined whether pay parity existed between workers doing similar jobs.","href":"SAT_Words_276_300.html"},{"number":294,"word":"Perfunctory","partOfSpeech":"","meaning":"Done with little care, interest, or effort because it is only a routine duty.","synonyms":["cursory","routine","careless"],"antonyms":[],"example":"He gave the report a perfunctory glance before signing it.","href":"SAT_Words_276_300.html"},{"number":295,"word":"Prevalent","partOfSpeech":"","meaning":"Common or widespread at a particular time or place.","synonyms":["common","widespread","frequent"],"antonyms":[],"example":"Online learning became prevalent in many schools during the emergency.","href":"SAT_Words_276_300.html"},{"number":296,"word":"Provisional","partOfSpeech":"","meaning":"Arranged for the present but likely to change later; temporary.","synonyms":["temporary","tentative","conditional"],"antonyms":[],"example":"The school announced a provisional schedule while repairs were still underway.","href":"SAT_Words_276_300.html"},{"number":297,"word":"Requisite","partOfSpeech":"","meaning":"Required or necessary for a particular purpose.","synonyms":["necessary","essential","required"],"antonyms":[],"example":"A signed permission form is a requisite for joining the field trip.","href":"SAT_Words_276_300.html"},{"number":298,"word":"Retain","partOfSpeech":"","meaning":"To keep, continue to have, or remember.","synonyms":["keep","preserve","maintain"],"antonyms":[],"example":"The museum retained the original photographs in its archive.","href":"SAT_Words_276_300.html"},{"number":299,"word":"Spurious","partOfSpeech":"","meaning":"False or not genuine, even though it may appear to be true.","synonyms":["false","counterfeit","misleading"],"antonyms":[],"example":"The editor rejected the article because its main claim was based on spurious evidence.","href":"SAT_Words_276_300.html"},{"number":300,"word":"Synthesize","partOfSpeech":"","meaning":"To combine separate ideas, information, or parts into a coherent whole.","synonyms":["combine","integrate","unify"],"antonyms":[],"example":"The student synthesized evidence from several sources to form a strong conclusion.","href":"SAT_Words_276_300.html"},{"number":301,"word":"Substantiate","partOfSpeech":"verb","meaning":"To support or prove a claim with evidence or facts.","synonyms":["support","verify","corroborate"],"antonyms":["refute","disprove"],"example":"The researcher used additional data to substantiate her conclusion.","href":"SAT_Words_301_325.html"},{"number":302,"word":"Caveat","partOfSpeech":"noun","meaning":"A warning, condition, or limitation that must be considered.","synonyms":["warning","qualification","proviso"],"antonyms":["assurance","guarantee"],"example":"The recommendation came with the caveat that the study involved only a small sample.","href":"SAT_Words_301_325.html"},{"number":303,"word":"Corollary","partOfSpeech":"noun","meaning":"A result or conclusion that follows naturally from an established fact or principle.","synonyms":["consequence","result","deduction"],"antonyms":["premise","cause"],"example":"A corollary of longer life expectancy is a growing need for elder care.","href":"SAT_Words_301_325.html"},{"number":304,"word":"Dichotomy","partOfSpeech":"noun","meaning":"A division or contrast between two sharply different ideas or groups.","synonyms":["division","contrast","split"],"antonyms":["unity","continuity"],"example":"The essay challenges the false dichotomy between economic growth and environmental protection.","href":"SAT_Words_301_325.html"},{"number":305,"word":"Ramification","partOfSpeech":"noun","meaning":"A consequence, especially one that is indirect or complicated.","synonyms":["consequence","implication","repercussion"],"antonyms":["cause","origin"],"example":"The committee considered every ramification of changing the admission policy.","href":"SAT_Words_301_325.html"},{"number":306,"word":"Tangential","partOfSpeech":"adjective","meaning":"Only slightly related to the main subject; moving away from the central point.","synonyms":["peripheral","digressive","incidental"],"antonyms":["central","relevant"],"example":"The speaker omitted a tangential anecdote so the presentation would remain focused.","href":"SAT_Words_301_325.html"},{"number":307,"word":"Assert","partOfSpeech":"verb","meaning":"To state a claim confidently and forcefully.","synonyms":["declare","maintain","affirm"],"antonyms":["deny","retract"],"example":"The author asserts that public libraries strengthen civic participation.","href":"SAT_Words_301_325.html"},{"number":308,"word":"Conjecture","partOfSpeech":"noun / verb","meaning":"A conclusion or prediction based on incomplete evidence; to form such a conclusion.","synonyms":["speculation","hypothesis","surmise"],"antonyms":["certainty","proof"],"example":"Without additional records, the historian could only conjecture why the settlement was abandoned.","href":"SAT_Words_301_325.html"},{"number":309,"word":"Postulate","partOfSpeech":"verb / noun","meaning":"To propose an idea as a basis for reasoning or discussion.","synonyms":["propose","presume","theorize"],"antonyms":["disprove","reject"],"example":"The model postulates that access to transportation affects employment rates.","href":"SAT_Words_301_325.html"},{"number":310,"word":"Delineate","partOfSpeech":"verb","meaning":"To describe, define, or mark the limits of something precisely.","synonyms":["outline","define","depict"],"antonyms":["obscure","blur"],"example":"The report clearly delineates the responsibilities of each agency.","href":"SAT_Words_301_325.html"},{"number":311,"word":"Stipulate","partOfSpeech":"verb","meaning":"To state a condition or requirement explicitly as part of an agreement.","synonyms":["specify","require","prescribe"],"antonyms":["waive","omit"],"example":"The grant rules stipulate that all funds must be used for educational programs.","href":"SAT_Words_301_325.html"},{"number":312,"word":"Qualify","partOfSpeech":"verb","meaning":"To limit, modify, or make a statement less absolute.","synonyms":["modify","limit","temper"],"antonyms":["intensify","generalize"],"example":"The critic qualified her praise by noting that the final chapter felt rushed.","href":"SAT_Words_301_325.html"},{"number":313,"word":"Elicit","partOfSpeech":"verb","meaning":"To draw out or bring forth a response, reaction, or piece of information.","synonyms":["evoke","prompt","extract"],"antonyms":["suppress","stifle"],"example":"The interviewer asked open-ended questions to elicit detailed responses.","href":"SAT_Words_301_325.html"},{"number":314,"word":"Exemplify","partOfSpeech":"verb","meaning":"To serve as a clear example of a quality, idea, or pattern.","synonyms":["illustrate","demonstrate","embody"],"antonyms":["contradict","misrepresent"],"example":"The building exemplifies the architect’s preference for simple geometric forms.","href":"SAT_Words_301_325.html"},{"number":315,"word":"Paradigm","partOfSpeech":"noun","meaning":"A model, pattern, or widely accepted way of understanding something.","synonyms":["model","framework","pattern"],"antonyms":["anomaly","exception"],"example":"The discovery produced a new paradigm for understanding planetary formation.","href":"SAT_Words_301_325.html"},{"number":316,"word":"Proponent","partOfSpeech":"noun","meaning":"A person who supports or advocates for an idea or proposal.","synonyms":["advocate","supporter","champion"],"antonyms":["opponent","critic"],"example":"Proponents of the plan argue that it will reduce traffic congestion.","href":"SAT_Words_301_325.html"},{"number":317,"word":"Partisan","partOfSpeech":"adjective / noun","meaning":"Strongly committed to one side, often in a way that limits objectivity.","synonyms":["biased","one-sided","sectarian"],"antonyms":["impartial","nonpartisan"],"example":"The article’s partisan tone made its analysis seem less trustworthy.","href":"SAT_Words_301_325.html"},{"number":318,"word":"Subjective","partOfSpeech":"adjective","meaning":"Based on personal feelings, interpretations, or opinions rather than objective facts.","synonyms":["personal","interpretive","biased"],"antonyms":["objective","factual"],"example":"Judgments about beauty are often subjective and vary across cultures.","href":"SAT_Words_301_325.html"},{"number":319,"word":"Intrinsic","partOfSpeech":"adjective","meaning":"Belonging naturally or essentially to something; inherent.","synonyms":["inherent","essential","innate"],"antonyms":["extrinsic","external"],"example":"Curiosity has intrinsic value even when it produces no immediate practical benefit.","href":"SAT_Words_301_325.html"},{"number":320,"word":"Tacit","partOfSpeech":"adjective","meaning":"Understood or implied without being stated directly.","synonyms":["implicit","unspoken","understood"],"antonyms":["explicit","stated"],"example":"By remaining silent, the committee gave tacit approval to the proposal.","href":"SAT_Words_301_325.html"},{"number":321,"word":"Prescient","partOfSpeech":"adjective","meaning":"Showing accurate knowledge of or insight into future events.","synonyms":["foresighted","prophetic","far-seeing"],"antonyms":["shortsighted","unaware"],"example":"Her prescient warning about water shortages prompted early conservation efforts.","href":"SAT_Words_301_325.html"},{"number":322,"word":"Discern","partOfSpeech":"verb","meaning":"To recognize, detect, or understand something that is not immediately obvious.","synonyms":["perceive","detect","distinguish"],"antonyms":["overlook","miss"],"example":"Researchers could discern a pattern only after combining several years of data.","href":"SAT_Words_301_325.html"},{"number":323,"word":"Obfuscate","partOfSpeech":"verb","meaning":"To make something unclear, confusing, or difficult to understand.","synonyms":["obscure","confuse","cloud"],"antonyms":["clarify","explain"],"example":"The excessive jargon served to obfuscate a relatively simple argument.","href":"SAT_Words_301_325.html"},{"number":324,"word":"Belie","partOfSpeech":"verb","meaning":"To contradict or give a false impression of something.","synonyms":["contradict","misrepresent","disguise"],"antonyms":["confirm","reveal"],"example":"Her calm expression belied the anxiety she felt before the performance.","href":"SAT_Words_301_325.html"},{"number":325,"word":"Subsume","partOfSpeech":"verb","meaning":"To include or absorb something within a broader category or concept.","synonyms":["include","incorporate","encompass"],"antonyms":["exclude","separate"],"example":"The broad category of renewable energy subsumes solar, wind, and hydroelectric power.","href":"SAT_Words_301_325.html"},{"number":326,"word":"Circumscribe","partOfSpeech":"verb","meaning":"To restrict something within limits or define its boundaries.","synonyms":["limit","confine","bound"],"antonyms":["expand","liberate"],"example":"The law circumscribes the agency’s authority to collect personal data.","href":"SAT_Words_326_350.html"},{"number":327,"word":"Connotation","partOfSpeech":"noun","meaning":"An associated or implied meaning beyond a word’s literal definition.","synonyms":["association","implication","undertone"],"antonyms":["denotation","literal meaning"],"example":"The word “home” often carries a connotation of safety and belonging.","href":"SAT_Words_326_350.html"},{"number":328,"word":"Denotation","partOfSpeech":"noun","meaning":"The direct, literal, or dictionary meaning of a word.","synonyms":["definition","literal meaning","reference"],"antonyms":["connotation","implication"],"example":"Although the two terms share a similar denotation, their emotional associations differ.","href":"SAT_Words_326_350.html"},{"number":329,"word":"Euphemism","partOfSpeech":"noun","meaning":"A mild or indirect expression used in place of one considered harsh or unpleasant.","synonyms":["substitute","understatement","circumlocution"],"antonyms":["bluntness","directness"],"example":"The phrase “passed away” is a common euphemism for “died.”","href":"SAT_Words_326_350.html"},{"number":330,"word":"Syntax","partOfSpeech":"noun","meaning":"The arrangement of words and phrases to create well-formed sentences.","synonyms":["sentence structure","word order","grammar"],"antonyms":["disorder","incoherence"],"example":"The poet’s unusual syntax slows the reader and emphasizes each image.","href":"SAT_Words_326_350.html"},{"number":331,"word":"Mitigate","partOfSpeech":"verb","meaning":"To make something harmful, serious, or painful less severe.","synonyms":["lessen","alleviate","reduce"],"antonyms":["aggravate","intensify"],"example":"Planting trees can mitigate the urban heat-island effect.","href":"SAT_Words_326_350.html"},{"number":332,"word":"Alleviate","partOfSpeech":"verb","meaning":"To relieve or reduce pain, difficulty, or a problem.","synonyms":["relieve","ease","lessen"],"antonyms":["worsen","aggravate"],"example":"The new bus route helped alleviate transportation problems for rural residents.","href":"SAT_Words_326_350.html"},{"number":333,"word":"Augment","partOfSpeech":"verb","meaning":"To increase the size, value, or effectiveness of something by adding to it.","synonyms":["increase","enhance","expand"],"antonyms":["diminish","reduce"],"example":"The museum augmented its exhibit with interactive maps and recordings.","href":"SAT_Words_326_350.html"},{"number":334,"word":"Facilitate","partOfSpeech":"verb","meaning":"To make an action or process easier or more likely to occur.","synonyms":["enable","assist","ease"],"antonyms":["hinder","impede"],"example":"Shared digital records facilitate cooperation among medical specialists.","href":"SAT_Words_326_350.html"},{"number":335,"word":"Stymie","partOfSpeech":"verb","meaning":"To prevent or hinder progress.","synonyms":["thwart","obstruct","impede"],"antonyms":["assist","advance"],"example":"A shortage of reliable data may stymie efforts to evaluate the program.","href":"SAT_Words_326_350.html"},{"number":336,"word":"Curtail","partOfSpeech":"verb","meaning":"To reduce, limit, or cut something short.","synonyms":["reduce","restrict","shorten"],"antonyms":["extend","expand"],"example":"The city curtailed water use during the prolonged drought.","href":"SAT_Words_326_350.html"},{"number":337,"word":"Bolster","partOfSpeech":"verb","meaning":"To support, strengthen, or reinforce something.","synonyms":["strengthen","support","fortify"],"antonyms":["weaken","undermine"],"example":"New archaeological evidence bolstered the historian’s interpretation.","href":"SAT_Words_326_350.html"},{"number":338,"word":"Attenuate","partOfSpeech":"verb","meaning":"To reduce the force, effect, or intensity of something.","synonyms":["weaken","diminish","lessen"],"antonyms":["amplify","intensify"],"example":"Dense vegetation can attenuate noise from a nearby highway.","href":"SAT_Words_326_350.html"},{"number":339,"word":"Escalate","partOfSpeech":"verb","meaning":"To increase rapidly in intensity, seriousness, or extent.","synonyms":["intensify","increase","mount"],"antonyms":["subside","decrease"],"example":"The disagreement escalated when neither side agreed to compromise.","href":"SAT_Words_326_350.html"},{"number":340,"word":"Burgeoning","partOfSpeech":"adjective","meaning":"Growing or developing rapidly.","synonyms":["expanding","flourishing","growing"],"antonyms":["declining","shrinking"],"example":"The region’s burgeoning technology sector attracted skilled workers.","href":"SAT_Words_326_350.html"},{"number":341,"word":"Nascent","partOfSpeech":"adjective","meaning":"Just beginning to exist or develop.","synonyms":["emerging","incipient","developing"],"antonyms":["mature","established"],"example":"The nascent research field had only a few published studies.","href":"SAT_Words_326_350.html"},{"number":342,"word":"Inception","partOfSpeech":"noun","meaning":"The beginning or establishment of an activity, organization, or process.","synonyms":["beginning","outset","origin"],"antonyms":["conclusion","termination"],"example":"The program has served thousands of students since its inception.","href":"SAT_Words_326_350.html"},{"number":343,"word":"Cessation","partOfSpeech":"noun","meaning":"The stopping or ending of an action or process.","synonyms":["ending","halt","termination"],"antonyms":["continuation","inception"],"example":"The cessation of mining allowed the damaged landscape to recover.","href":"SAT_Words_326_350.html"},{"number":344,"word":"Wane","partOfSpeech":"verb / noun","meaning":"To decrease gradually in strength, size, or importance.","synonyms":["decline","diminish","fade"],"antonyms":["grow","intensify"],"example":"Public interest began to wane after the issue disappeared from the news.","href":"SAT_Words_326_350.html"},{"number":345,"word":"Modulate","partOfSpeech":"verb","meaning":"To adjust or regulate the degree, tone, or intensity of something.","synonyms":["regulate","adjust","vary"],"antonyms":["fix","intensify"],"example":"The speaker modulated her voice to emphasize the most important points.","href":"SAT_Words_326_350.html"},{"number":346,"word":"Temper","partOfSpeech":"verb","meaning":"To moderate, soften, or restrain the force of something.","synonyms":["moderate","soften","restrain"],"antonyms":["intensify","inflame"],"example":"The author tempered his criticism by acknowledging the study’s strengths.","href":"SAT_Words_326_350.html"},{"number":347,"word":"Paramount","partOfSpeech":"adjective","meaning":"More important than anything else; supreme.","synonyms":["foremost","supreme","primary"],"antonyms":["minor","secondary"],"example":"Protecting participants’ safety was paramount throughout the experiment.","href":"SAT_Words_326_350.html"},{"number":348,"word":"Paucity","partOfSpeech":"noun","meaning":"A scarcity or insufficient amount of something.","synonyms":["scarcity","shortage","dearth"],"antonyms":["abundance","plenty"],"example":"A paucity of written records makes the period difficult to study.","href":"SAT_Words_326_350.html"},{"number":349,"word":"Superfluous","partOfSpeech":"adjective","meaning":"Unnecessary because more than enough is already present.","synonyms":["unnecessary","excessive","redundant"],"antonyms":["essential","necessary"],"example":"The editor removed superfluous details that distracted from the main argument.","href":"SAT_Words_326_350.html"},{"number":350,"word":"Tenuous","partOfSpeech":"adjective","meaning":"Weak, slight, or not strongly supported.","synonyms":["weak","fragile","insubstantial"],"antonyms":["strong","substantial"],"example":"The claim rests on a tenuous connection between two unrelated trends.","href":"SAT_Words_326_350.html"},{"number":351,"word":"Juxtapose","partOfSpeech":"verb","meaning":"To place two things close together for comparison or contrast.","synonyms":["compare","contrast","set beside"],"antonyms":["separate","isolate"],"example":"The exhibit juxtaposes traditional tools with modern machines.","href":"SAT_Words_351_375.html"},{"number":352,"word":"Antithetical","partOfSpeech":"adjective","meaning":"Directly opposed or contrary to something.","synonyms":["opposed","contrary","incompatible"],"antonyms":["compatible","similar"],"example":"Censorship is antithetical to the journal’s commitment to open debate.","href":"SAT_Words_351_375.html"},{"number":353,"word":"Homogeneous","partOfSpeech":"adjective","meaning":"Consisting of parts or members that are similar in kind.","synonyms":["uniform","similar","consistent"],"antonyms":["diverse","heterogeneous"],"example":"Because the sample was homogeneous, the results may not apply to the broader population.","href":"SAT_Words_351_375.html"},{"number":354,"word":"Unilateral","partOfSpeech":"adjective","meaning":"Done by one person, group, or country without the agreement of others.","synonyms":["one-sided","independent","solo"],"antonyms":["mutual","multilateral"],"example":"The board criticized the director’s unilateral decision to cancel the program.","href":"SAT_Words_351_375.html"},{"number":355,"word":"Equivocal","partOfSpeech":"adjective","meaning":"Unclear, ambiguous, or open to more than one interpretation.","synonyms":["ambiguous","uncertain","evasive"],"antonyms":["unequivocal","clear"],"example":"The witness gave an equivocal response that did not confirm either account.","href":"SAT_Words_351_375.html"},{"number":356,"word":"Lucid","partOfSpeech":"adjective","meaning":"Clear and easy to understand.","synonyms":["clear","coherent","intelligible"],"antonyms":["confusing","obscure"],"example":"The textbook offers a lucid explanation of a difficult scientific concept.","href":"SAT_Words_351_375.html"},{"number":357,"word":"Abstruse","partOfSpeech":"adjective","meaning":"Difficult to understand because it is complex or highly technical.","synonyms":["obscure","complex","recondite"],"antonyms":["clear","accessible"],"example":"The article translated an abstruse theory into language for general readers.","href":"SAT_Words_351_375.html"},{"number":358,"word":"Esoteric","partOfSpeech":"adjective","meaning":"Intended for or understood by a small group with specialized knowledge.","synonyms":["specialized","arcane","obscure"],"antonyms":["common","accessible"],"example":"The seminar focused on esoteric questions in medieval philosophy.","href":"SAT_Words_351_375.html"},{"number":359,"word":"Meticulous","partOfSpeech":"adjective","meaning":"Extremely careful and attentive to detail.","synonyms":["precise","thorough","painstaking"],"antonyms":["careless","sloppy"],"example":"Her meticulous notes allowed the experiment to be replicated accurately.","href":"SAT_Words_351_375.html"},{"number":360,"word":"Astute","partOfSpeech":"adjective","meaning":"Showing sharp judgment and an ability to understand situations quickly.","synonyms":["perceptive","shrewd","insightful"],"antonyms":["naive","obtuse"],"example":"The analyst made an astute observation about the survey’s hidden bias.","href":"SAT_Words_351_375.html"},{"number":361,"word":"Profound","partOfSpeech":"adjective","meaning":"Very deep, significant, or intellectually insightful.","synonyms":["deep","significant","far-reaching"],"antonyms":["superficial","slight"],"example":"The invention had a profound effect on communication and commerce.","href":"SAT_Words_351_375.html"},{"number":362,"word":"Subtle","partOfSpeech":"adjective","meaning":"Not obvious; delicate or difficult to detect or describe.","synonyms":["nuanced","delicate","understated"],"antonyms":["obvious","blatant"],"example":"A subtle shift in tone reveals the narrator’s growing doubt.","href":"SAT_Words_351_375.html"},{"number":363,"word":"Rudimentary","partOfSpeech":"adjective","meaning":"Basic, elementary, or not yet fully developed.","synonyms":["basic","elementary","primitive"],"antonyms":["advanced","sophisticated"],"example":"The early device had only rudimentary controls but inspired later designs.","href":"SAT_Words_351_375.html"},{"number":364,"word":"Candor","partOfSpeech":"noun","meaning":"Honest, open, and direct expression.","synonyms":["honesty","frankness","openness"],"antonyms":["deception","evasion"],"example":"The committee appreciated her candor about the project’s limitations.","href":"SAT_Words_351_375.html"},{"number":365,"word":"Reticent","partOfSpeech":"adjective","meaning":"Reluctant to speak or reveal thoughts and feelings.","synonyms":["reserved","restrained","uncommunicative"],"antonyms":["outspoken","forthcoming"],"example":"The normally reticent scientist spoke publicly after the results were challenged.","href":"SAT_Words_351_375.html"},{"number":366,"word":"Cynical","partOfSpeech":"adjective","meaning":"Distrustful of people’s motives and inclined to expect selfishness.","synonyms":["skeptical","distrustful","pessimistic"],"antonyms":["trusting","idealistic"],"example":"The columnist was cynical about promises made during the campaign.","href":"SAT_Words_351_375.html"},{"number":367,"word":"Denigrate","partOfSpeech":"verb","meaning":"To criticize unfairly or belittle the value or reputation of something.","synonyms":["disparage","belittle","demean"],"antonyms":["praise","exalt"],"example":"The review should evaluate the theory rather than denigrate its supporters.","href":"SAT_Words_351_375.html"},{"number":368,"word":"Admonish","partOfSpeech":"verb","meaning":"To warn or reprimand someone firmly but usually constructively.","synonyms":["reprimand","caution","rebuke"],"antonyms":["praise","encourage"],"example":"The editor admonished the writer to verify every quotation.","href":"SAT_Words_351_375.html"},{"number":369,"word":"Ominous","partOfSpeech":"adjective","meaning":"Suggesting that something bad or threatening may happen.","synonyms":["threatening","foreboding","sinister"],"antonyms":["reassuring","auspicious"],"example":"The sudden drop in groundwater levels was an ominous sign for farmers.","href":"SAT_Words_351_375.html"},{"number":370,"word":"Auspicious","partOfSpeech":"adjective","meaning":"Suggesting a favorable or successful outcome.","synonyms":["promising","favorable","propitious"],"antonyms":["ominous","unfavorable"],"example":"The strong early results marked an auspicious beginning for the project.","href":"SAT_Words_351_375.html"},{"number":371,"word":"Seminal","partOfSpeech":"adjective","meaning":"Highly original and influential in shaping later ideas or developments.","synonyms":["influential","groundbreaking","foundational"],"antonyms":["derivative","insignificant"],"example":"Her seminal study changed how researchers understood language acquisition.","href":"SAT_Words_351_375.html"},{"number":372,"word":"Scrupulous","partOfSpeech":"adjective","meaning":"Very careful to be accurate, honest, and morally correct.","synonyms":["conscientious","meticulous","principled"],"antonyms":["careless","unscrupulous"],"example":"The journalist was scrupulous about confirming facts with multiple sources.","href":"SAT_Words_351_375.html"},{"number":373,"word":"Trivial","partOfSpeech":"adjective","meaning":"Of little importance, value, or seriousness.","synonyms":["minor","insignificant","petty"],"antonyms":["important","substantial"],"example":"The author argues that the disagreement is not trivial because it affects public safety.","href":"SAT_Words_351_375.html"},{"number":374,"word":"Futile","partOfSpeech":"adjective","meaning":"Incapable of producing a useful result; pointless.","synonyms":["pointless","ineffective","vain"],"antonyms":["effective","productive"],"example":"Without accurate measurements, further calculations would be futile.","href":"SAT_Words_351_375.html"},{"number":375,"word":"Harbor","partOfSpeech":"verb","meaning":"To hold or maintain a thought, feeling, or suspicion, often secretly.","synonyms":["hold","entertain","conceal"],"antonyms":["release","dismiss"],"example":"Several researchers harbored doubts about the reliability of the instrument.","href":"SAT_Words_351_375.html"}];
